async function main() {
  if (process.argv.includes('--inspect-policies')) {
    const policies = await query(`select tablename,policyname,roles,cmd,qual from pg_policies where schemaname='public' and tablename in ('pedidos','pedido_itens','enderecos_entrega') order by tablename,policyname`)
    console.log(JSON.stringify(policies))
    return
  }
  const [preflight] = await query(`select
    (select count(*) from (select lower(slug) from public.tenants group by 1 having count(*) > 1) d) as duplicate_slugs,
    (select count(*) from (select tenant_id,lower(trim(bairro)) from public.enderecos_entrega group by 1,2 having count(*) > 1) d) as duplicate_areas,
    (select count(*) from public.tenants t where
      ((to_jsonb(t)->>'latitude') is null) <> ((to_jsonb(t)->>'longitude') is null)
      or nullif(to_jsonb(t)->>'latitude','')::numeric not between -90 and 90
      or nullif(to_jsonb(t)->>'longitude','')::numeric not between -180 and 180) as invalid_coordinates,
    (select count(*) from public.enderecos_entrega where taxa is null or taxa < 0 or taxa > 100000) as invalid_fees
  `)
  if (Object.values(preflight).some((value) => Number(value) > 0)) {
    throw new Error(`Preflight bloqueado: ${JSON.stringify(preflight)}`)
  }

  for (const version of ['044', '045', '046']) {
    const file = fs.readdirSync('supabase/migrations').find((name) => name.startsWith(`${version}_`))
    if (!file) throw new Error(`Migration ${version} nao encontrada`)
    await query(fs.readFileSync(`supabase/migrations/${file}`, 'utf8'))
    console.log(`OK migration ${version}`)
  }

  const [state] = await query(`select
    to_regprocedure('public.criar_pedido_atomico(uuid,text,text,jsonb,jsonb,jsonb)') is not null as pedido_rpc,
    to_regprocedure('public.aceitar_convite_loja(text)') is not null as convite_rpc,
    to_regclass('public.convites_loja') is not null as convites,
    exists(select 1 from information_schema.columns where table_schema='public' and table_name='tenants' and column_name='latitude') as geo,
    not exists(select 1 from information_schema.role_table_grants where table_schema='public' and table_name in ('pedidos','pedido_itens') and grantee='anon') as anon_orders_revoked,
    not exists(select 1 from pg_policies where schemaname='public' and tablename in ('pedidos','pedido_itens') and policyname like 'Membros gerenciam%') as broad_policies_removed,
    exists(select 1 from pg_policies where schemaname='public' and tablename='enderecos_entrega' and policyname in ('Bairros ativos publicos','Bairros ativos públicos') and roles='{anon}' and cmd='SELECT' and qual like '%ativo = true%') as active_areas_policy
  `)
  if (!Object.values(state).every(Boolean)) throw new Error(`Verificacao final falhou: ${JSON.stringify(state)}`)
  console.log('OK migrations 044-046 aplicadas e verificadas')
}

main().catch((error) => { console.error(error.message); process.exit(1) })

// Regrava variáveis da Vercel sem BOM. Todos os valores vêm do ambiente.
const https = require('https')

const VERCEL_PATHS = [
  `${process.env.APPDATA}\\xdg.data\\com.vercel.cli\\auth.json`,
  `${process.env.APPDATA}\\com.vercel.cli\\Data\\auth.json`,
]

function required(name) {
  const value = process.env[name]?.trim()
  if (!value) throw new Error(`Variável obrigatória ausente: ${name}`)
  return value
}

function getVercelToken() {
  for (const path of VERCEL_PATHS) {
    try { return require(path).token } catch {}
  }
  return null
}

function api(token, projectId, method, path, body) {
  const data = body ? JSON.stringify(body) : null
  return new Promise((resolve, reject) => {
    const request = https.request({
      hostname: 'api.vercel.com', port: 443, path, method,
      headers: {
        Authorization: `Bearer ${token}`,
        'Content-Type': 'application/json',
        'Content-Length': data ? Buffer.byteLength(data) : 0,
      },
    }, response => {
      let result = ''
      response.on('data', chunk => { result += chunk })
      response.on('end', () => {
        try { resolve(JSON.parse(result)) } catch { resolve(result) }
      })
    })
    request.on('error', reject)
    if (data) request.write(data)
    request.end()
  })
}

async function setEnvVar(token, projectId, key, value, sensitive, targets = ['production', 'development', 'preview']) {
  const cleanValue = value.replace(/^\uFEFF/, '').trim()
  const list = await api(token, projectId, 'GET', `/v9/projects/${projectId}/env`)
  if (list.envs) {
    for (const env of list.envs.filter(item => item.key === key)) {
      await api(token, projectId, 'DELETE', `/v9/projects/${projectId}/env/${env.id}`)
      console.log(`  ${key}: configuração antiga removida`)
    }
  }
  return api(token, projectId, 'POST', `/v10/projects/${projectId}/env`, {
    key, value: cleanValue, type: sensitive ? 'sensitive' : 'encrypted', target: targets,
  })
}

async function main() {
  const vercelToken = getVercelToken()
  if (!vercelToken) throw new Error('Token da Vercel não encontrado no login local da CLI')
  const projectId = required('VERCEL_PROJECT_ID')
  const supabaseToken = required('SUPABASE_ACCESS_TOKEN')
  const projectRef = required('SUPABASE_PROJECT_REF')
  const adminEmail = required('ADMIN_EMAIL')
  const adminPassword = required('ADMIN_PASSWORD')
  const adminSessionSecret = required('ADMIN_SESSION_SECRET')

  const apiKeys = await new Promise((resolve, reject) => {
    const request = https.request({
      hostname: 'api.supabase.com',
      path: `/v1/projects/${projectRef}/api-keys`,
      headers: { Authorization: `Bearer ${supabaseToken}` },
    }, response => {
      let result = ''
      response.on('data', chunk => { result += chunk })
      response.on('end', () => resolve(JSON.parse(result)))
    })
    request.on('error', reject)
    request.end()
  })

  const anon = apiKeys.find(key => key.name === 'anon')?.api_key
  const serviceKey = apiKeys.find(key => key.name === 'service_role')?.api_key
  if (!anon || !serviceKey) throw new Error('Chaves esperadas não retornadas pelo Supabase')

  console.log('Regravando variáveis sem BOM (valores não serão exibidos)...')
  const values = {
    NEXT_PUBLIC_SUPABASE_URL: `https://${projectRef}.supabase.co`,
    NEXT_PUBLIC_SUPABASE_ANON_KEY: anon,
    SUPABASE_SERVICE_ROLE_KEY: serviceKey,
    ADMIN_EMAIL: adminEmail,
    ADMIN_PASSWORD: adminPassword,
    ADMIN_SESSION_SECRET: adminSessionSecret,
  }
  for (const [key, value] of Object.entries(values)) {
    const sensitive = ['SUPABASE_SERVICE_ROLE_KEY', 'ADMIN_PASSWORD', 'ADMIN_SESSION_SECRET'].includes(key)
    await setEnvVar(vercelToken, projectId, key, value, sensitive)
    console.log(`  ${key}: atualizada`)
  }
  console.log('Variáveis atualizadas sem exibir valores')
}

main().catch(error => {
  console.error('Falha ao atualizar variáveis:', error.message)
  process.exit(1)
})

// Script que gera src/data/cidades/[UF].ts para os 26 estados restantes
// Usa a API oficial do IBGE: https://servicodados.ibge.gov.br
const https = require('https')
const fs = require('fs')
const path = require('path')

const UFS = ['AC','AL','AP','AM','BA','CE','DF','ES','GO','MT','MS','MG','PA','PB','PR','PE','PI','RJ','RN','RS','RO','RR','SC','SP','SE','TO']

function fetchUF(uf) {
  return new Promise((resolve, reject) => {
    const req = https.request({
      hostname: 'servicodados.ibge.gov.br',
      path: `/api/v1/localidades/estados/${uf}/municipios`,
      method: 'GET',
    }, res => {
      let d = ''
      res.on('data', c => d += c)
      res.on('end', () => {
        try { resolve(JSON.parse(d)) } catch (e) { reject(e) }
      })
    })
    req.on('error', reject)
    req.end()
  })
}

async function main() {
  const outDir = path.join(__dirname, '..', 'src', 'data', 'cidades')
  fs.mkdirSync(outDir, { recursive: true })

  for (const uf of UFS) {
    process.stdout.write(`${uf}... `)
    try {
      const cidades = await fetchUF(uf)
      const nomes = cidades.map(c => c.nome).sort((a, b) => a.localeCompare(b, 'pt-BR'))
      const content = `export const CIDADES = ${JSON.stringify(nomes, null, 2)}\n`
      fs.writeFileSync(path.join(outDir, `${uf}.ts`), content)
      console.log(`${nomes.length} cidades`)
    } catch (e) {
      console.error(`ERRO em ${uf}:`, e.message)
    }
  }
  console.log('✓ Pronto')
}

main().catch(e => { console.error(e); process.exit(1) })

const fs = require('fs')

const { query: sql } = require('./lib/supabase-management')


async function run() {
  const result = await sql(`
    DO $$
    DECLARE
      v_tenant uuid;
      v_produto uuid;
      v_frutas uuid;
      v_adicionais uuid;
      v_comp uuid;
      v_nome text;
      v_ordem integer;
    BEGIN
      SELECT id INTO STRICT v_tenant FROM tenants WHERE slug = 'typeacai';
      UPDATE categorias SET nome='Monte do seu jeito' WHERE tenant_id=v_tenant AND ativo=true AND lower(nome) LIKE 'monte%jeito%';
      SELECT id INTO STRICT v_produto FROM produtos
        WHERE tenant_id = v_tenant AND nome = 'Copo de 300ml' AND ativo = true
        ORDER BY created_at DESC LIMIT 1;

      SELECT id INTO v_frutas FROM categorias_complementos
        WHERE tenant_id=v_tenant AND id='3337e1bf-7997-4479-ae8a-2100b073e935';
      IF v_frutas IS NULL THEN
        INSERT INTO categorias_complementos (tenant_id,nome,ordem,ativo,qtd_minima,qtd_maxima,max_um_de_cada)
        VALUES (v_tenant,'Frutas',1,true,0,2,true) RETURNING id INTO v_frutas;
      ELSE
        UPDATE categorias_complementos SET nome='Frutas',ordem=1,ativo=true,qtd_minima=0,qtd_maxima=2,max_um_de_cada=true
        WHERE id=v_frutas;
      END IF;

      SELECT id INTO v_adicionais FROM categorias_complementos
        WHERE tenant_id=v_tenant AND lower(nome)=lower('Adicionais') LIMIT 1;
      IF v_adicionais IS NULL THEN
        INSERT INTO categorias_complementos (tenant_id,nome,ordem,ativo,qtd_minima,qtd_maxima,max_um_de_cada)
        VALUES (v_tenant,'Adicionais',2,true,0,3,true) RETURNING id INTO v_adicionais;
      ELSE
        UPDATE categorias_complementos SET ordem=2,ativo=true,qtd_minima=0,qtd_maxima=3,max_um_de_cada=true
        WHERE id=v_adicionais;
      END IF;

      FOR v_nome, v_ordem IN SELECT * FROM (VALUES ('Banana',1),('Maçã',2)) x(nome,ordem) LOOP
        SELECT id INTO v_comp FROM complementos WHERE tenant_id=v_tenant AND lower(nome)=lower(v_nome) LIMIT 1;
        IF v_comp IS NULL THEN
          INSERT INTO complementos (tenant_id,nome,preco,ativo,categoria_id,ordem,qtd_max)
          VALUES (v_tenant,v_nome,0,true,v_frutas,v_ordem,1) RETURNING id INTO v_comp;
        ELSE
          UPDATE complementos SET ativo=true,categoria_id=v_frutas,ordem=v_ordem,qtd_max=1 WHERE id=v_comp;
        END IF;
        INSERT INTO produto_complementos (produto_id,complemento_id) VALUES (v_produto,v_comp)
        ON CONFLICT DO NOTHING;
      END LOOP;

      FOR v_nome, v_ordem IN SELECT * FROM (VALUES ('Leite em Pó',1),('Leite Condensado',2),('Sucrilhos',3)) x(nome,ordem) LOOP
        SELECT id INTO v_comp FROM complementos WHERE tenant_id=v_tenant AND lower(nome)=lower(v_nome) LIMIT 1;
        IF v_comp IS NULL THEN
          INSERT INTO complementos (tenant_id,nome,preco,ativo,categoria_id,ordem,qtd_max)
          VALUES (v_tenant,v_nome,0,true,v_adicionais,v_ordem,1) RETURNING id INTO v_comp;
        ELSE
          UPDATE complementos SET ativo=true,categoria_id=v_adicionais,ordem=v_ordem,qtd_max=1 WHERE id=v_comp;
        END IF;
        INSERT INTO produto_complementos (produto_id,complemento_id) VALUES (v_produto,v_comp)
        ON CONFLICT DO NOTHING;
      END LOOP;
    END $$;

    SELECT cc.nome AS lista, cc.ordem, cc.qtd_minima, cc.qtd_maxima,
      json_agg(c.nome ORDER BY c.ordem) AS itens
    FROM categorias_complementos cc
    JOIN complementos c ON c.categoria_id=cc.id AND c.ativo
    JOIN produto_complementos pc ON pc.complemento_id=c.id
    JOIN produtos p ON p.id=pc.produto_id
    JOIN tenants t ON t.id=p.tenant_id
    WHERE t.slug='typeacai' AND p.nome='Copo de 300ml' AND p.ativo
    GROUP BY cc.id, cc.nome, cc.ordem, cc.qtd_minima, cc.qtd_maxima
    ORDER BY cc.ordem;
  `)
  console.log(JSON.stringify(result, null, 2))
}

run().catch((error) => { console.error(error.message); process.exit(1) })

// Valida as credenciais necessárias para preparar um deploy.
// Não grava nem imprime valores sensíveis.
const https = require('https')
const { required } = require('./lib/supabase-management')

async function verifySupabaseAccess() {
  const accessToken = required('SUPABASE_ACCESS_TOKEN')
  const projectRef = required('SUPABASE_PROJECT_REF')
  return new Promise((resolve, reject) => {
    const request = https.request({
      hostname: 'api.supabase.com',
      path: `/v1/projects/${projectRef}/api-keys`,
      method: 'GET',
      headers: { Authorization: `Bearer ${accessToken}` },
    }, response => {
      let body = ''
      response.on('data', chunk => { body += chunk })
      response.on('end', () => {
        if (response.statusCode !== 200) return reject(new Error(`Supabase recusou a solicitação (HTTP ${response.statusCode})`))
        const keys = JSON.parse(body)
        if (!keys.some(key => key.name === 'service_role')) return reject(new Error('Chave service_role não encontrada'))
        resolve()
      })
    })
    request.on('error', reject)
    request.end()
  })
}

verifySupabaseAccess()
  .then(() => console.log('Credenciais de deploy validadas sem exibir ou gravar segredos'))
  .catch(error => { console.error(error.message); process.exit(1) })

