    const c = v.replace(/\D/g, '')
    if (c.length <= 11) return c.replace(/(\d{2})(\d{5})(\d{0,4})/, '($1) $2-$3').trim()
    return v
  }

  const formatCpf = (v: string) => {
    const c = v.replace(/\D/g, '').slice(0, 11)
    return c
      .replace(/(\d{3})(\d{3})(\d{3})(\d{2})/, '$1.$2.$3-$4')
      .replace(/(\d{3})(\d{3})(\d{3})/, '$1.$2.$3')
      .replace(/(\d{3})(\d{3})/, '$1.$2')
