function DesignTab() {
  const [paleta, setPaleta] = useState('verde-classica')
  const [layout, setLayout] = useState('classico')
  const [loading, setLoading] = useState(true)
  const [saving, setSaving] = useState(false)
  const [saved, setSaved] = useState(false)
  const [message, setMessage] = useState<{ type: 'ok' | 'error'; text: string } | null>(null)
  const [tenant, setTenant] = useState<any>(null)
  const [whatsapp, setWhatsapp] = useState({ ativo: true, numero: '', mensagem: 'Olá! Estou no seu site e preciso de ajuda.' })
  const [aviso, setAviso] = useState({ ativo: false, mensagem: '', fundo: '#111827', texto: '#FFFFFF', link: '' })
  const [faixas, setFaixas] = useState({ topoTextos: '', topoAnimacao: 'continuo', velocidade: 12, segundaAtiva: false, segundaMensagem: '', segundaLink: '' })
  const [cores, setCores] = useState<Record<ColorKey,string>>({ primary: '#16A34A', secondary: '#15803D', accent: '#F97316' })
  const [tipografia, setTipografia] = useState<'classica' | 'moderna' | 'minimalista'>('classica')
  const supabase = createClient()

  useEffect(() => {
    loadConfig()
  }, [])

  const loadConfig = async () => {
    const { data: user } = await supabase.auth.getUser()
    if (!user.user) { setLoading(false); return }
    const tid = await activeTenantId()
    if (!tid) { setLoading(false); return }

    const { data: tenantData, error } = await supabase
      .from('tenants')
      .select('config, slug, logo_url, banner_url')
      .eq('id', tid)
      .single()

    if (error) setMessage({ type: 'error', text: error.message })
    setTenant(tenantData)
    if (tenantData?.config) {
      const cfg = tenantData.config as any
      if (cfg.cardapio_layout) setLayout(cfg.cardapio_layout)
      if (cfg.cardapio_paleta) setPaleta(cfg.cardapio_paleta)
      if (cfg.cardapio_cores) setCores((atual) => ({ primary: cfg.cardapio_cores.primary || atual.primary, secondary: cfg.cardapio_cores.secondary || atual.secondary, accent: cfg.cardapio_cores.accent || atual.accent }))
      if (['classica','moderna','minimalista'].includes(cfg.cardapio_tipografia)) setTipografia(cfg.cardapio_tipografia)
      setWhatsapp({ ativo: cfg.cardapio_whatsapp_ativo !== false, numero: cfg.cardapio_whatsapp_numero || '', mensagem: cfg.cardapio_whatsapp_mensagem || 'Olá! Estou no seu site e preciso de ajuda.' })
      setAviso({ ativo: cfg.cardapio_aviso_ativo === true, mensagem: cfg.cardapio_aviso_mensagem || '', fundo: cfg.cardapio_aviso_fundo || '#111827', texto: cfg.cardapio_aviso_texto || '#FFFFFF', link: cfg.cardapio_aviso_link || '' })
      setFaixas({ topoTextos: Array.isArray(cfg.cardapio_aviso_textos) ? cfg.cardapio_aviso_textos.join('\n') : (cfg.cardapio_aviso_mensagem || ''), topoAnimacao: cfg.cardapio_aviso_animacao || 'continuo', velocidade: Number(cfg.cardapio_aviso_velocidade || 12), segundaAtiva: cfg.cardapio_segunda_faixa_ativa === true, segundaMensagem: cfg.cardapio_segunda_faixa_mensagem || '', segundaLink: cfg.cardapio_segunda_faixa_link || '' })
      const banners = Array.isArray(cfg.cardapio_banners) ? cfg.cardapio_banners : []
      setTenant({ ...tenantData, banners: [0, 1, 2].map((i) => banners[i]?.url || (i === 0 ? tenantData.banner_url : '') || '') })
    }
    setLoading(false)
  }

  const salvarDesign = async () => {
    setSaving(true)
    setMessage(null)
    try {
      const { data: { user } } = await supabase.auth.getUser()
      if (!user) throw new Error('Sessao expirada. Entre novamente.')
      const tid = await activeTenantId()
      if (!tid) throw new Error('Loja ativa não encontrada.')
      const { data: current, error: readError } = await supabase.from('tenants').select('config, slug').eq('id', tid).single()
      if (readError) throw readError
      if ([...Object.values(cores), aviso.fundo, aviso.texto].some(cor => !HEX_COLOR.test(cor))) throw new Error('Revise as cores. Use HEX com 6 caracteres, por exemplo #16A34A.')
      for (const link of [aviso.link, faixas.segundaLink]) { if (link) { try { const u=new URL(link); if (!['http:','https:'].includes(u.protocol)) throw new Error() } catch { throw new Error('Os links das faixas devem começar com http:// ou https://') } } }
      const novoConfig = { ...((current?.config || {}) as any), cardapio_layout: layout, cardapio_paleta: paleta, cardapio_cores: cores, cardapio_tipografia: tipografia,
        cardapio_whatsapp_ativo: whatsapp.ativo, cardapio_whatsapp_numero: whatsapp.numero, cardapio_whatsapp_mensagem: whatsapp.mensagem,
        cardapio_aviso_ativo: aviso.ativo, cardapio_aviso_mensagem: aviso.mensagem, cardapio_aviso_textos: faixas.topoTextos.split('\n').map(v=>v.trim()).filter(Boolean), cardapio_aviso_animacao: faixas.topoAnimacao, cardapio_aviso_velocidade: faixas.velocidade, cardapio_aviso_fundo: aviso.fundo, cardapio_aviso_texto: aviso.texto, cardapio_aviso_link: aviso.link, cardapio_segunda_faixa_ativa: faixas.segundaAtiva, cardapio_segunda_faixa_mensagem: faixas.segundaMensagem, cardapio_segunda_faixa_link: faixas.segundaLink }
      const { error: updateError } = await supabase.from('tenants').update({ config: novoConfig }).eq('id', tid)
      if (updateError) throw updateError
      const response = await fetch('/api/revalidate-cardapio', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ slug: current.slug }) })
      const result = await response.json()
      if (!response.ok) throw new Error(result.error || 'Design salvo, mas o cardapio nao foi atualizado.')
      setSaved(true)
      setMessage({ type: 'ok', text: 'Design salvo e cardapio publico atualizado.' })
      setTimeout(() => setSaved(false), 2000)
    } catch (error: any) {
      setMessage({ type: 'error', text: error.message || 'Erro ao salvar o design.' })
    } finally { setSaving(false) }
  }

  if (loading) return <div className="text-center py-8 hint">Carregando...</div>

  return (
    <div className="space-y-5">
      <div className="grid grid-cols-1 md:grid-cols-2 gap-5">
        <AssetUpload tipo="logo" titulo="Logomarca do negocio" url={tenant?.logo_url || ''} onChanged={(url) => setTenant((t: any) => ({ ...t, logo_url: url }))} slug={tenant?.slug} />
        {[0, 1, 2].map((slot) => <AssetUpload key={slot} tipo="banner" slot={slot} titulo={`Banner principal ${slot + 1}`} url={tenant?.banners?.[slot] || ''} onChanged={(url) => setTenant((t: any) => { const banners = [...(t?.banners || ['', '', ''])]; banners[slot] = url; return { ...t, banners } })} slug={tenant?.slug} />)}
      </div>
      <div className="glass p-6">
        <div className="eyebrow mb-1">Aparência</div>
        <h2 className="text-lg font-semibold mb-2">Layout do cardápio</h2>
        <p className="hint text-xs mb-5">O layout define como os produtos aparecem no cardápio público</p>
        <div className="grid grid-cols-1 md:grid-cols-3 gap-3">
          {[
            { id: 'classico', nome: 'Classic', desc: 'Layout atual completo', disabled: false },
          ].map((l) => (
            <button
              key={l.id}
              onClick={() => !l.disabled && setLayout(l.id)}
              disabled={l.disabled && layout !== l.id}
              className="text-left p-4 rounded-2xl transition"
              style={
                layout === l.id
                  ? { background: 'rgba(22,163,74,.08)', border: '2px solid rgba(22,163,74,.4)' }
                  : { background: 'rgba(255,255,255,.5)', border: '1px solid var(--line)' }
              }
            >
              <div className="flex items-center justify-between mb-2">
                <LayoutIcon size={20} style={{ color: layout === l.id ? 'var(--green)' : 'var(--ink-muted)' }} />
                {layout === l.id && <Check size={16} style={{ color: 'var(--green)' }} strokeWidth={2.5} />}
              </div>
              <div className="text-sm font-semibold mb-1">{l.nome}</div>
              <div className="hint text-xs">{l.desc}</div>
            </button>
          ))}
        </div>
      </div>
      <div className="glass p-6 space-y-4">
        <div><div className="eyebrow mb-1">Atendimento</div><h2 className="text-lg font-semibold">Botão do WhatsApp</h2></div>
        <label className="flex items-center gap-2"><input type="checkbox" checked={whatsapp.ativo} onChange={(e) => setWhatsapp({ ...whatsapp, ativo: e.target.checked })} /> Ativar botão</label>
        <div className="grid md:grid-cols-2 gap-3"><input value={whatsapp.numero} onChange={(e) => setWhatsapp({ ...whatsapp, numero: e.target.value })} placeholder="Número com DDD" /><input value={whatsapp.mensagem} onChange={(e) => setWhatsapp({ ...whatsapp, mensagem: e.target.value })} placeholder="Mensagem predefinida" /></div>
        {whatsapp.ativo && <div className="rounded-xl p-3 bg-green-500 text-white text-center font-semibold">WhatsApp •” {whatsapp.mensagem || 'Prévia da mensagem'}</div>}
      </div>
      <div className="glass p-6 space-y-4">
        <div><div className="eyebrow mb-1">Comunicação</div><h2 className="text-lg font-semibold">Faixa de avisos</h2></div>
        <label className="flex items-center gap-2"><input type="checkbox" checked={aviso.ativo} onChange={(e) => setAviso({ ...aviso, ativo: e.target.checked })} /> Ativar faixa</label>
        <input value={aviso.mensagem} onChange={(e) => setAviso({ ...aviso, mensagem: e.target.value })} placeholder="Ex: Frete grátis acima de R$ 50,00" />
        <textarea rows={3} value={faixas.topoTextos} onChange={e=>setFaixas({...faixas,topoTextos:e.target.value})} placeholder="Textos do topo, um por linha" />
        <div className="grid md:grid-cols-2 gap-3"><label className="text-sm">Animação<select value={faixas.topoAnimacao} onChange={e=>setFaixas({...faixas,topoAnimacao:e.target.value})}><option value="continuo">Contínuo</option><option value="onda">Onda</option><option value="piscar">Piscar</option></select></label><label className="text-sm">Velocidade ({faixas.velocidade}s)<input type="range" min="4" max="30" value={faixas.velocidade} onChange={e=>setFaixas({...faixas,velocidade:Number(e.target.value)})}/></label></div>
        <div className="border-t pt-4 space-y-3"><label className="flex items-center gap-2"><input type="checkbox" checked={faixas.segundaAtiva} onChange={e=>setFaixas({...faixas,segundaAtiva:e.target.checked})}/> Ativar segunda faixa após os dados da loja</label><input value={faixas.segundaMensagem} onChange={e=>setFaixas({...faixas,segundaMensagem:e.target.value})} placeholder="Mensagem da segunda faixa"/><input value={faixas.segundaLink} onChange={e=>setFaixas({...faixas,segundaLink:e.target.value})} placeholder="Link opcional"/></div>
        <div className="grid md:grid-cols-3 gap-3"><HexColorField label="Cor do fundo" value={aviso.fundo} onChange={(fundo) => setAviso({ ...aviso, fundo })}/><HexColorField label="Cor do texto" value={aviso.texto} onChange={(texto) => setAviso({ ...aviso, texto })}/><label className="text-sm">Link opcional<input value={aviso.link} onChange={(e) => setAviso({ ...aviso, link: e.target.value })} placeholder="https://..." /></label></div>
        {aviso.ativo && <div className="rounded-xl p-3 text-center font-semibold" style={{ background: aviso.fundo, color: aviso.texto }}>{aviso.mensagem || 'Prévia da faixa de avisos'}</div>}
      </div>

      <div className="glass p-6">
        <div className="eyebrow mb-1">Identidade</div>
        <h2 className="text-lg font-semibold mb-2">Cores personalizadas</h2>
        <p className="hint text-xs mb-5">Defina tres cores em HEX. Fundo, textos e botoes sao calculados automaticamente.</p>
        <div className="grid md:grid-cols-3 gap-3 mb-5">{([{id:'classica',nome:'Clássica',fonte:'Playfair Display / Lato'},{id:'moderna',nome:'Moderna',fonte:'Poppins / Inter'},{id:'minimalista',nome:'Minimalista',fonte:'Montserrat'}] as const).map(op => <button type="button" key={op.id} onClick={() => setTipografia(op.id)} aria-pressed={tipografia===op.id} className="text-left p-3 rounded-xl border" style={{borderColor:tipografia===op.id?cores.primary:'var(--line)',background:tipografia===op.id?`${cores.primary}12`:'white'}}><b>{op.nome}</b><span className="block text-xs opacity-70">{op.fonte}</span></button>)}</div>
        <div className="grid sm:grid-cols-2 lg:grid-cols-3 gap-4">{([['primary','Principal'],['secondary','Secundaria'],['accent','Destaque']] as const).map(([key,label]) => <HexColorField key={key} label={label} value={cores[key]} onChange={(value) => setCores({...cores,[key]:normalizeHex(value)})}/>)}</div>
        {(() => { const preview=getCardapioTheme(paleta,cores); return <div className={`mt-6 rounded-2xl overflow-hidden border wd-font-${tipografia}`} style={{background:preview.background,color:preview.text,borderColor:preview.secondary}}><div className="p-4" style={{background:preview.primary,color:'#fff'}}><div className="wd-heading font-bold text-xl">Previa da sua loja</div><div className="text-sm">Identidade Classic</div></div><div className="p-4"><span className="inline-block px-2 py-1 rounded-full text-xs font-bold" style={{background:preview.accent,color:preview.text}}>DESTAQUE</span><h3 className="wd-heading font-bold mt-3">Produto especial</h3><p className="text-sm opacity-75">Descricao, categorias e produtos usam sua identidade.</p><div className="flex justify-between items-center mt-4"><b style={{color:preview.secondary}}>R$ 29,90</b><button className="px-4 py-2 rounded-xl text-white" style={{background:preview.button}}>Adicionar</button></div></div></div> })()}
      </div>

      <button
        onClick={salvarDesign}
        disabled={saving}
        className={`btn-primary w-full justify-center ${saved ? 'opacity-90' : ''}`}
        style={saved ? { background: '#15803D' } : undefined}
      >
        {saving ? 'Salvando...' : saved ? '✓ Salvo!' : 'Salvar design'}
      </button>
      {message && <div className="text-sm text-center p-3 rounded-2xl" style={{ background: message.type === 'ok' ? 'rgba(22,163,74,.1)' : 'rgba(220,38,38,.1)', color: message.type === 'ok' ? '#15803D' : '#B91C1C' }}>{message.text}</div>}
    </div>
  )
}

function AssetUpload({ tipo, titulo, url, onChanged, slug, slot = 0 }: { tipo: 'logo' | 'banner'; titulo: string; url: string; onChanged: (url: string) => void; slug?: string; slot?: number }) {
  const [uploading, setUploading] = useState(false)
  const [error, setError] = useState('')
  const inputId = `cardapio-${tipo}-${slot}-input`
  const revalidate = async () => {
    if (!slug) return
    const response = await fetch('/api/revalidate-cardapio', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ slug }) })
    if (!response.ok) throw new Error('Imagem salva, mas a atualizacao do cardapio falhou.')
  }
  const authHeaders = async (): Promise<Record<string, string>> => {
    const { data: { session } } = await createClient().auth.getSession()
    return session?.access_token ? { Authorization: `Bearer ${session.access_token}` } : {}
  }
  const upload = async (file: File) => {
    setError('')
    if (!['image/jpeg', 'image/png', 'image/webp'].includes(file.type)) return setError('Use JPG, PNG ou WebP.')
    if (file.size > 5 * 1024 * 1024) return setError('A imagem deve ter no maximo 5MB.')
    const dimensoes = await new Promise<{ width: number; height: number }>((resolve, reject) => {
      const image = new Image()
      image.onload = () => { URL.revokeObjectURL(image.src); resolve({ width: image.naturalWidth, height: image.naturalHeight }) }
      image.onerror = reject
      image.src = URL.createObjectURL(file)
    })
    const esperado = tipo === 'banner' ? { width: 1080, height: 600 } : { width: 1080, height: 1080 }
    if (dimensoes.width !== esperado.width || dimensoes.height !== esperado.height) return setError(`Use uma imagem de exatamente ${esperado.width} × ${esperado.height} px. A selecionada tem ${dimensoes.width} × ${dimensoes.height} px.`)
    setUploading(true)
    try {
      const form = new FormData()
      form.append('file', file)
      form.append('tipo', tipo)
      form.append('slot', String(slot))
      const response = await fetch('/api/upload-cardapio-asset', { method: 'POST', body: form, headers: await authHeaders() })
      const result = await response.json()
      if (!response.ok) throw new Error(result.error || 'Erro no upload')
      onChanged(result.url)
      await revalidate()
    } catch (e: any) { setError(e.message) } finally { setUploading(false) }
  }
  const remove = async () => {
    setUploading(true)
    setError('')
    try {
      const response = await fetch(`/api/upload-cardapio-asset?tipo=${tipo}&slot=${slot}`, { method: 'DELETE', headers: await authHeaders() })
      const result = await response.json()
      if (!response.ok) throw new Error(result.error || 'Erro ao remover')
      onChanged('')
      try { await revalidate() } catch { /* a imagem removida continua removida mesmo se o cache falhar */ }
    } catch (e: any) { setError(e.message) } finally { setUploading(false) }
  }
  return <div className="glass p-6">
    <div className="eyebrow mb-1">Identidade visual</div>
    <h2 className="text-lg font-semibold mb-4">{titulo}</h2>
    <button type="button" onClick={() => document.getElementById(inputId)?.click()} className="w-full min-h-36 rounded-2xl border-2 border-dashed flex items-center justify-center overflow-hidden" style={{ borderColor: 'var(--line)' }}>
      {url ? <img src={url} alt={titulo} className={tipo === 'banner' ? 'w-full h-40 object-cover' : 'size-28 object-contain'} /> : <span className="flex flex-col items-center gap-2 hint"><Upload size={24} />{uploading ? 'Enviando...' : 'Clique para enviar'}</span>}
    </button>
    <input id={inputId} className="hidden" type="file" accept="image/jpeg,image/png,image/webp" onChange={(e) => { const f = e.target.files?.[0]; if (f) upload(f); e.currentTarget.value = '' }} />
    {url && <button type="button" onClick={remove} disabled={uploading} className="mt-3 text-sm text-red-600">Remover imagem</button>}
    <p className="hint text-xs mt-2">{tipo === 'banner' ? '1080 x 600 px' : '1080 x 1080 px'} - JPG, PNG ou WebP - ate 5MB.</p>
    {error && <div className="mt-3 rounded-xl border-2 border-red-300 bg-red-50 p-3 text-red-800"><p className="font-bold text-sm">Nao foi possivel enviar esta imagem</p><p className="text-sm mt-1">{error}</p></div>}
  </div>
}

function ProdutosTab() {
  const [categorias, setCategorias] = useState<any[]>([])
  const [categoriasProduto, setCategoriasProduto] = useState<any[]>([])
  const [produtos, setProdutos] = useState<Record<string, any[]>>({})
  const [complementosPorProduto, setComplementosPorProduto] = useState<Record<string, any[]>>({})
  const [loading, setLoading] = useState(true)
  const [showCatModal, setShowCatModal] = useState(false)
  const [showProdModal, setShowProdModal] = useState(false)
  const [novaCat, setNovaCat] = useState('')
  const [novaCatBanner, setNovaCatBanner] = useState('')

  const [editingProduto, setEditingProduto] = useState<any>(null)
  const [editingCat, setEditingCat] = useState<any>(null)
  const [showTipoModal, setShowTipoModal] = useState(false)
  const [novoTipo, setNovoTipo] = useState('')
  const supabase = createClient()

  useEffect(() => { loadData() }, [])

  const loadData = async () => {
    const { data: user } = await supabase.auth.getUser()
    if (!user.user) { setLoading(false); return }
    const tid = await activeTenantId()
    if (!tid) return

    const { data: cats } = await supabase
      .from('categorias')
      .select('*')
      .eq('tenant_id', tid)
      .eq('ativo', true)
      .order('ordem')
    setCategorias(cats || [])
    const { data: tipos } = await supabase.from('categorias_produtos').select('*').eq('tenant_id', tid).eq('ativo', true).order('ordem')
    setCategoriasProduto(tipos || [])

    if (cats) {
      const prods: Record<string, any[]> = {}
      for (const cat of cats) {
        const { data: p } = await supabase
          .from('produtos')
          .select('*')
          .eq('tenant_id', tid)
          .eq('categoria_id', cat.id)
          .eq('ativo', true)
          .order('ordem')
        prods[cat.id] = p || []
      }
      setProdutos(prods)

      // Mapear quantidade de complementos por produto
      const ids = Object.values(prods).flat().map((p: any) => p.id)
      if (ids.length > 0) {
        const { data: pcs } = await supabase
          .from('produto_complementos')
          .select('produto_id')
          .in('produto_id', ids)
        const map: Record<string, any[]> = {}
        pcs?.forEach((r: any) => {
          if (!map[r.produto_id]) map[r.produto_id] = []
          map[r.produto_id].push(r)
        })
        setComplementosPorProduto(map)
      }
    }
    setLoading(false)
  }

  const criarCategoria = async () => {
    if (!novaCat.trim()) return
    const { data: user } = await supabase.auth.getUser()
    if (!user.user) return
    await supabase.from('categorias').insert({
      tenant_id: await activeTenantId(),
      nome: novaCat,
      ordem: categorias.length,
      imagem_url: novaCatBanner.trim() || null,
    })
    setNovaCat('')
    setShowCatModal(false)
    setEditingCat(null)
    loadData()
  }

  const criarTipoProduto = async () => {
    if (!novoTipo.trim()) return
    const { data: user } = await supabase.auth.getUser()
    if (!user.user) return
    const { error } = await supabase.from('categorias_produtos').insert({ tenant_id: await activeTenantId(), nome: novoTipo.trim(), ordem: categoriasProduto.length })
    if (error) return alert(`Não foi possível criar a categoria: ${error.message}`)
    setNovoTipo('')
    setShowTipoModal(false)
    loadData()
  }

  const atualizarCategoria = async () => {
    if (!editingCat || !novaCat.trim()) return
    const { data: user } = await supabase.auth.getUser()
    if (!user.user) return
    await supabase
      .from('categorias')
      .update({ nome: novaCat, imagem_url: novaCatBanner.trim() || null })
      .eq('id', editingCat.id)
    setNovaCat('')
    setShowCatModal(false)
    setEditingCat(null)
    loadData()
  }

  const deletarCategoria = async (id: string) => {
    if (!confirm('Tem certeza? Produtos desta categoria ficarão sem categoria.')) return
    await supabase.from('categorias').update({ ativo: false }).eq('id', id)
    loadData()
  }

  const abrirModalProduto = (produto?: any) => {
    setEditingProduto(produto || null)
    setShowProdModal(true)
  }

  const deletarProduto = async (id: string) => {
    if (!confirm('Tem certeza que deseja excluir este produto?')) return
    await supabase.from('produtos').update({ ativo: false }).eq('id', id)
    loadData()
  }

  const temCategorias = categorias.length > 0

  return (
    <div className="space-y-5">
      {/* Header com botões */}
      <div className="glass p-5 flex flex-wrap items-center justify-between gap-3">
        <div>
          <div className="eyebrow mb-1">Organização</div>
          <h2 className="text-lg font-semibold">Produtos</h2>
        </div>
        <div className="flex gap-2">
          <button onClick={() => { setEditingCat(null); setNovaCat(''); setShowCatModal(true) }} className="btn-primary">
            <Plus size={14} />Nova sessão
          </button>
          {false && <button onClick={() => { setNovoTipo(''); setShowTipoModal(true) }} className="btn-ghost">
            <Plus size={14} />Nova categoria
          </button>}
          <button
            onClick={() => abrirModalProduto()}
            disabled={!temCategorias}
            className="btn-ghost"
            style={{
              opacity: temCategorias ? 1 : 0.5,
              cursor: temCategorias ? 'pointer' : 'not-allowed',
            }}
            title={!temCategorias ? 'Crie uma sessão antes' : ''}
          >
            <Plus size={14} />Novo produto
          </button>
        </div>
      </div>

      {false && categoriasProduto.length > 0 && <div className="glass p-4">
        <div className="text-sm font-semibold mb-2">Categorias de atalho</div>
        <div className="flex flex-wrap gap-2">
          {categoriasProduto.map((tipo) => <span key={tipo.id} className="inline-flex items-center gap-2 px-3 py-1.5 rounded-full border text-sm" style={{ borderColor: 'var(--line)' }}>
            {tipo.nome}
            <button type="button" aria-label={`Remover ${tipo.nome}`} className="text-red-600" onClick={async () => { if (!confirm(`Remover a categoria ${tipo.nome}?`)) return; await supabase.from('categorias_produtos').update({ ativo: false }).eq('id', tipo.id); loadData() }}> × </button>
          </span>)}
        </div>
      </div>}

      {/* Estado vazio */}
      {!loading && !temCategorias && (
        <div className="glass p-8 text-center">
          <div className="size-16 mx-auto mb-4 rounded-2xl flex items-center justify-center" style={{ background: 'rgba(245,158,11,.14)' }}>
            <AlertCircle size={28} style={{ color: '#92400E' }} />
          </div>
          <h3 className="text-lg font-semibold mb-2" style={{ color: 'var(--ink)' }}>
            Vamos começar!
          </h3>
          <p className="hint mb-5 max-w-sm mx-auto">
            Para cadastrar seu primeiro produto, crie uma sessão antes.
          </p>
          <button onClick={() => setShowCatModal(true)} className="btn-primary">
            <Plus size={14} />Criar primeira sessão
          </button>
        </div>
      )}

      {/* Lista de sessões */}
      {loading ? (
        <div className="text-center py-8 hint">Carregando...</div>
      ) : (
        temCategorias && (
          <div className="space-y-3">
            {categorias.map((cat) => (
              <div key={cat.id} className="glass p-5">
                <div className="flex items-center justify-between mb-3">
                  <div>
                    <h3 className="text-base font-semibold">{cat.nome}</h3>
                    <p className="hint text-xs">{produtos[cat.id]?.length || 0} produto(s)</p>
                  </div>
                  <div className="flex gap-1">
                    <button className="btn-icon-round" onClick={() => { setEditingCat(cat); setNovaCat(cat.nome); setNovaCatBanner(cat.imagem_url || ''); setShowCatModal(true) }}>
                      <Edit size={14} />
                    </button>
                    <button className="btn-icon-round" onClick={() => deletarCategoria(cat.id)}>
                      <Trash2 size={14} />
                    </button>
                  </div>
                </div>
                {produtos[cat.id]?.length > 0 ? (
                  <div className="space-y-2">
                    {produtos[cat.id].map((prod) => (
                      <ProdutoLinha
                        key={prod.id}
                        produto={prod}
                        complementosCount={(complementosPorProduto[prod.id] || []).length}
                        onEdit={() => abrirModalProduto(prod)}
                        onToggleAtivo={async () => {
                          await supabase.from('produtos').update({ ativo: !prod.ativo }).eq('id', prod.id)
                          loadData()
                        }}
                        onDuplicate={async () => {
                          await supabase.from('produtos').insert({
                            tenant_id: prod.tenant_id,
                            categoria_id: prod.categoria_id,
                            categoria_produto_id: prod.categoria_produto_id,
                            nome: prod.nome + ' (cópia)',
                            descricao: prod.descricao,
                            preco: prod.preco,
                            preco_riscado: prod.preco_riscado,
                            imagem_url: prod.imagem_url,
                            imagem_path: prod.imagem_path,
                            tempo_preparo_min: prod.tempo_preparo_min,
                            ordem: prod.ordem,
                            codigo_externo: prod.codigo_externo,
                            pontos: prod.pontos,
                            etiquetas: prod.etiquetas,
                            disponivel_mesa: prod.disponivel_mesa,
                            disponivel_delivery: prod.disponivel_delivery,
                            disponivel_retirada: prod.disponivel_retirada,
                            ativo: true,
                          })
                          loadData()
                        }}
                        onUpdate={async (field: string, value: any) => {
                          await supabase.from('produtos').update({ [field]: value }).eq('id', prod.id)
                          loadData()
                        }}
                        onDelete={() => deletarProduto(prod.id)}
                      />
                    ))}
                  </div>
                ) : (
                  <div className="text-center py-4 hint text-sm">
                    Nenhum produto nesta sessão
                  </div>
                )}
              </div>
            ))}
          </div>
        )
      )}

      {/* Modal nova/editar sessão */}
      {showCatModal && (
        <div className="fixed inset-0 bg-black/50 backdrop-blur-sm flex items-center justify-center z-50 p-4">
          <div className="glass-strong rounded-3xl p-6 w-full max-w-md">
            <h2 className="text-lg font-semibold mb-1">{editingCat ? 'Editar sessão' : 'Nova sessão'}</h2>
            <p className="hint text-xs mb-4">Ex: Monte do seu jeito, Combos, Promoções</p>
            <label>Nome da sessão</label>
            <input
              value={novaCat}
              onChange={(e) => setNovaCat(e.target.value)}
              placeholder="Ex: Monte do seu jeito"
              autoFocus
            />
            <div className="flex gap-3 mt-5">
              <button onClick={() => { setShowCatModal(false); setEditingCat(null); setNovaCat('') }} className="btn-ghost flex-1 justify-center">
                Cancelar
              </button>
              <button onClick={editingCat ? atualizarCategoria : criarCategoria} className="btn-primary flex-1 justify-center">
                {editingCat ? 'Salvar' : 'Criar'}
              </button>
            </div>
          </div>
        </div>
      )}

      {false && showTipoModal && (
        <div className="fixed inset-0 bg-black/50 backdrop-blur-sm flex items-center justify-center z-50 p-4">
          <div className="glass-strong rounded-3xl p-6 w-full max-w-md">
            <h2 className="text-lg font-semibold mb-1">Nova categoria</h2>
            <p className="hint text-xs mb-4">Atalho por tipo de produto. Ex: Hambúrgueres, Pizzas, Bebidas.</p>
            <label>Nome da categoria</label>
            <input value={novoTipo} onChange={(e) => setNovoTipo(e.target.value)} placeholder="Ex: Bebidas" autoFocus />
            <div className="flex gap-3 mt-5">
              <button onClick={() => setShowTipoModal(false)} className="btn-ghost flex-1 justify-center">Cancelar</button>
              <button onClick={criarTipoProduto} className="btn-primary flex-1 justify-center">Criar</button>
            </div>
          </div>
        </div>
      )}

      {/* Modal novo/editar produto •” usa componente dedicado com abas estilo InstaDelivery */}
      {showProdModal && (
        <ProdutoFormModal
          produto={editingProduto}
          categorias={categorias}
          categoriasProduto={categoriasProduto}
          onClose={() => { setShowProdModal(false); setEditingProduto(null) }}
          onSaved={loadData}
        />
      )}
    </div>
  )
}

﻿'use client'

import { useState, useEffect } from 'react'
import { createClient } from '@/lib/supabase/client'
import { activeTenantId } from '@/lib/active-tenant-client'
import {
  Plus, Edit, Trash2, Search, X, Save, Users,
  Phone, Mail, Calendar, Filter, Download
} from 'lucide-react'
import { formatCurrency } from '@/lib/utils'

type Cliente = {
  id: string
  nome: string
  telefone: string
  email: string | null
  endereco: string | null
  bairro: string | null
  cep: string | null
  referencia: string | null
  data_nascimento: string | null
  observacoes: string | null
  tags: string[] | null
  ativo: boolean
  opt_in_whatsapp: boolean
  total_pedidos: number
  ultimo_pedido_em: string | null
  primeiro_pedido_em: string | null
  ltv: number
  created_at: string
}

const TAGS_RAPIDAS = [
  { id: 'vip', label: '⭐ VIP', color: '#FEF9C3', fg: '#854D0E' },
  { id: 'novo', label: '✨ Novo', color: '#DBEAFE', fg: '#1E3A8A' },
  { id: 'inativo', label: 'Inativo', color: '#F3F4F6', fg: '#374151' },
  { id: 'aniversariante', label: '🎂 Aniversariante', color: '#FCE7F3', fg: '#9D174D' },
  { id: 'fidelidade', label: '💚 Fidelidade', color: '#DCFCE7', fg: '#166534' },
]

export default function ClientesPage() {
  const [clientes, setClientes] = useState<Cliente[]>([])
  const [loading, setLoading] = useState(true)
  const [busca, setBusca] = useState('')
  const [filtroTag, setFiltroTag] = useState('')
  const [filtroAtivo, setFiltroAtivo] = useState('todos')
  const [showModal, setShowModal] = useState(false)
  const [editing, setEditing] = useState<Cliente | null>(null)
  const supabase = createClient()

  useEffect(() => { loadData() }, [])

  const loadData = async () => {
    const tenantId = await activeTenantId()
    if (!tenantId) { setLoading(false); return }
    const tid = tenantId

    const { data, error } = await supabase
      .from('clientes')
      .select('*')
      .eq('tenant_id', tid)
      .order('ultimo_pedido_em', { ascending: false, nullsFirst: false })

    if (!error) setClientes(data || [])
    setLoading(false)
  }

  const deletar = async (id: string) => {
    if (!confirm('Tem certeza que deseja remover este cliente? Os pedidos existentes serão mantidos.')) return
    await supabase.from('clientes').delete().eq('id', id)
    loadData()
  }

  const abrirModal = (c?: Cliente) => {
    setEditing(c || null)
    setShowModal(true)
  }

  // Métricas resumo
  const totalClientes = clientes.filter(c => c.ativo).length
  const ltvMedio = clientes.filter(c => c.ativo).length > 0
    ? clientes.filter(c => c.ativo).reduce((acc, c) => acc + Number(c.ltv), 0) /
      clientes.filter(c => c.ativo).length
    : 0
  const maisFieis = [...clientes]
    .filter(c => c.ativo)
    .sort((a, b) => (b.total_pedidos || 0) - (a.total_pedidos || 0))
    .slice(0, 3)
  const novosClientes30d = clientes.filter(c => {
    if (!c.created_at) return false
    const dias = (Date.now() - new Date(c.created_at).getTime()) / (1000 * 60 * 60 * 24)
    return dias <= 30 && c.ativo
  }).length

  // Filtro
  const filtrados = clientes.filter((c) => {
    if (busca) {
      const b = busca.toLowerCase()
      const match =
        (c.nome || '').toLowerCase().includes(b) ||
        (c.telefone || '').toLowerCase().includes(b) ||
        (c.email || '').toLowerCase().includes(b)
      if (!match) return false
    }
    if (filtroTag) {
      if (!c.tags || !c.tags.includes(filtroTag)) return false
    }
    if (filtroAtivo === 'ativos' && !c.ativo) return false
    if (filtroAtivo === 'inativos' && c.ativo) return false
    return true
  })

  return (
    <div>
      {/* Header */}
      <div className="bg-white rounded-2xl border p-5 mb-4 flex items-center justify-between gap-3" style={{ borderColor: '#E5E7EB' }}>
        <div>
          <div className="text-xs text-gray-500 mb-1 flex items-center gap-1.5">
            <Users size={11} />
            Meus Clientes
          </div>
          <h1 className="text-3xl font-bold tracking-tight text-gray-900">
            CRM de Clientes
          </h1>
          <p className="text-sm text-gray-500 mt-1">
            Cadastre, segmente e acompanhe quem compra mais na sua loja.
          </p>
        </div>
        <div className="flex gap-2">
          <button
            onClick={() => exportarCSV(clientes)}
            className="btn-ghost"
            disabled={clientes.length === 0}
            title="Exportar CSV"
          >
            <Download size={14} />
            Exportar
          </button>
          <button onClick={() => abrirModal()} className="btn-primary">
            <Plus size={14} />
            Novo cliente
          </button>
        </div>
      </div>

      {/* Cards resumo */}
      <div className="grid grid-cols-2 md:grid-cols-4 gap-3 mb-4">
        <MetricCard label="Total de clientes" value={totalClientes} icon={Users} color="#16A34A" />
        <MetricCard label="LTV médio" value={formatCurrency(ltvMedio)} icon={Star} color="#EAB308" />
        <MetricCard label="Novos (30d)" value={novosClientes30d} icon={Plus} color="#3B82F6" />
        <MetricCard
          label="Top 3 mais fiéis"
          value=""
          icon={Trophy}
          color="#A855F7"
          topList={maisFieis}
        />
      </div>

      {/* Filtros */}
      <div className="bg-white rounded-2xl border p-4 mb-4 flex flex-wrap gap-3" style={{ borderColor: '#E5E7EB' }}>
        <div className="relative flex-1 min-w-[200px]">
          <Search size={14} className="absolute left-3 top-1/2 -translate-y-1/2 text-gray-400" />
          <input
            value={busca}
            onChange={(e) => setBusca(e.target.value)}
            placeholder="Nome, telefone ou email"
            className="form-input pl-9"
          />
        </div>
        <select
          value={filtroTag}
          onChange={(e) => setFiltroTag(e.target.value)}
          className="form-input flex-1 min-w-[180px]"
        >
          <option value="">Todas as tags</option>
          {TAGS_RAPIDAS.map((t) => (
            <option key={t.id} value={t.id}>{t.label}</option>
          ))}
        </select>
        <select
          value={filtroAtivo}
          onChange={(e) => setFiltroAtivo(e.target.value)}
          className="form-input flex-1 min-w-[180px]"
        >
          <option value="todos">Ativos e inativos</option>
          <option value="ativos">Apenas ativos</option>
          <option value="inativos">Apenas inativos</option>
        </select>
      </div>

      {/* Tabela */}
      <div className="bg-white rounded-2xl border overflow-hidden" style={{ borderColor: '#E5E7EB' }}>
        {loading ? (
          <div className="text-center py-12 text-gray-500">Carregando clientes...</div>
        ) : filtrados.length === 0 ? (
          <div className="text-center py-12 text-gray-500">
            {clientes.length === 0
              ? 'Nenhum cliente cadastrado ainda. Clique em "Novo cliente" pra começar.'
              : 'Nenhum cliente encontrado com esses filtros.'}
          </div>
        ) : (
          <table className="w-full">
            <thead className="bg-gray-50 text-xs text-gray-500 uppercase">
              <tr>
                <th className="text-left px-4 py-3">Cliente</th>
                <th className="text-left px-4 py-3">Telefone</th>
                <th className="text-left px-4 py-3">Tags</th>
                <th className="text-right px-4 py-3">Pedidos</th>
                <th className="text-right px-4 py-3">LTV</th>
                <th className="text-left px-4 py-3">Último pedido</th>
                <th className="text-left px-4 py-3">Ações</th>
              </tr>
            </thead>
            <tbody>
              {filtrados.map((c) => {
                const tagsCliente = (c.tags || []).map(id =>
                  TAGS_RAPIDAS.find(t => t.id === id)
                ).filter(Boolean) as any[]
                return (
                  <tr key={c.id} className="border-t" style={{ borderColor: '#F3F4F6' }}>
                    <td className="px-4 py-3">
                      <div className="font-medium text-gray-900">{c.nome}</div>
                      {c.email && <div className="text-xs text-gray-500">{c.email}</div>}
                      {c.data_nascimento && (
                        <div className="text-xs text-gray-400 flex items-center gap-1 mt-0.5">
                          <Calendar size={10} />
                          {formatarDataNasc(c.data_nascimento)}
                        </div>
                      )}
                      {!c.ativo && (
                        <span className="inline-block mt-1 text-[10px] px-1.5 py-0.5 rounded bg-gray-100 text-gray-500">Inativo</span>
                      )}
                    </td>
                    <td className="px-4 py-3 text-sm">
                      <a
                        href={`https://wa.me/55${(c.telefone || '').replace(/\D/g, '')}`}
                        target="_blank"
                        rel="noopener noreferrer"
                        className="text-gray-700 hover:text-green-600 flex items-center gap-1"
                      >
                        <Phone size={11} />
                        {c.telefone}
                      </a>
                    </td>
                    <td className="px-4 py-3">
                      <div className="flex flex-wrap gap-1">
                        {tagsCliente.length === 0 ? (
                          <span className="text-xs text-gray-400">—</span>
                        ) : (
                          tagsCliente.map((t) => (
                            <span
                              key={t.id}
                              className="inline-block px-1.5 py-0.5 rounded text-[10px] font-medium"
                              style={{ background: t.color, color: t.fg }}
                            >
                              {t.label}
                            </span>
                          ))
                        )}
                      </div>
                    </td>
                    <td className="px-4 py-3 text-right">
                      <div className="text-sm font-semibold text-gray-900">{c.total_pedidos || 0}</div>
                    </td>
                    <td className="px-4 py-3 text-right">
                      <div className="text-sm font-semibold text-green-700">
                        {formatCurrency(Number(c.ltv) || 0)}
                      </div>
                    </td>
                    <td className="px-4 py-3 text-xs text-gray-500">
                      {c.ultimo_pedido_em
                        ? tempoRelativo(c.ultimo_pedido_em)
                        : <span className="text-gray-400">Nunca pediu</span>}
                    </td>
                    <td className="px-4 py-3">
                      <div className="flex items-center gap-1">
                        <button
                          onClick={() => abrirModal(c)}
                          className="size-7 rounded-lg hover:bg-gray-100 flex items-center justify-center text-gray-600"
                          title="Editar"
                        >
                          <Edit size={12} />
                        </button>
                        <button
                          onClick={() => deletar(c.id)}
                          className="size-7 rounded-lg hover:bg-red-50 flex items-center justify-center text-red-600"
                          title="Apagar"
                        >
                          <Trash2 size={12} />
                        </button>
                      </div>
                    </td>
                  </tr>
                )
              })}
            </tbody>
          </table>
        )}
      </div>

      {showModal && (
        <ClienteModal
          cliente={editing}
          onClose={() => { setShowModal(false); setEditing(null) }}
          onSaved={loadData}
        />
      )}
    </div>
  )
}

