async function getActiveTenant(){const r=await fetch('/api/auth/session',{cache:'no-store'});const b=await r.json();if(!r.ok||!b.tenant?.id)throw new Error('Loja ativa não encontrada');return String(b.tenant.id)}

export default function EmbaixadoresPage(){
 const db=createClient(); const [lista,setLista]=useState<any[]>([]); const [indicacoes,setIndicacoes]=useState<any[]>([]); const [form,setForm]=useState({nome:'',email:'',telefone:'',codigo:'',tipo_comissao:'percentual',comissao_percentual:'0',comissao_fixa:'0'}); const [msg,setMsg]=useState('')
 async function load(){const tid=await getActiveTenant(); const [a,b]=await Promise.all([db.from('embaixadores').select('*').eq('tenant_id',tid).order('created_at',{ascending:false}),db.from('indicacoes_embaixador').select('*,embaixadores(nome)').eq('tenant_id',tid).order('created_at',{ascending:false})]);setLista(a.data||[]);setIndicacoes(b.data||[])}
 useEffect(()=>{load()},[])
 async function criar(e:React.FormEvent){e.preventDefault();const tid=await getActiveTenant();const codigo=(form.codigo||form.nome).normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/[^a-zA-Z0-9]/g,'').toUpperCase();const {error}=await db.from('embaixadores').insert({...form,codigo,tenant_id:tid,comissao_percentual:Number(form.comissao_percentual),comissao_fixa:Number(form.comissao_fixa)});setMsg(error?.message||'Embaixador cadastrado.');if(!error){setForm({nome:'',email:'',telefone:'',codigo:'',tipo_comissao:'percentual',comissao_percentual:'0',comissao_fixa:'0'});load()}}
 async function status(id:string,status_comissao:string){await db.from('indicacoes_embaixador').update({status_comissao,pago_em:status_comissao==='paga'?new Date().toISOString():null}).eq('id',id);load()}
 const total=useMemo(()=>indicacoes.filter(i=>i.status_comissao!=='cancelada').reduce((s,i)=>s+Number(i.valor_comissao||0),0),[indicacoes])
 return <div><header className="bg-white border rounded-2xl p-5 mb-4"><p className="text-xs text-gray-500 flex gap-1"><Users size={13}/> Crescimento</p><h1 className="text-3xl font-bold">Embaixadores</h1><p className="text-sm text-gray-500">Codigos de indicacao, conversoes, comissoes e pagamentos.</p></header><div className="grid md:grid-cols-3 gap-3 mb-4"><Card l="Embaixadores" v={lista.length}/><Card l="Indicacoes" v={indicacoes.length}/><Card l="Comissoes" v={formatCurrency(total)}/></div>
 <form onSubmit={criar} className="bg-white border rounded-2xl p-4 grid md:grid-cols-4 gap-3 mb-4"><input required className="form-input" placeholder="Nome" value={form.nome} onChange={e=>setForm({...form,nome:e.target.value})}/><input className="form-input" placeholder="E-mail" value={form.email} onChange={e=>setForm({...form,email:e.target.value})}/><input className="form-input" placeholder="Codigo (automatico)" value={form.codigo} onChange={e=>setForm({...form,codigo:e.target.value})}/><select className="form-input" value={form.tipo_comissao} onChange={e=>setForm({...form,tipo_comissao:e.target.value})}><option value="percentual">Percentual</option><option value="fixa">Fixa</option></select><input type="number" step=".01" className="form-input" placeholder="Percentual" value={form.comissao_percentual} onChange={e=>setForm({...form,comissao_percentual:e.target.value})}/><input type="number" step=".01" className="form-input" placeholder="Valor fixo" value={form.comissao_fixa} onChange={e=>setForm({...form,comissao_fixa:e.target.value})}/><button className="btn-primary"><Plus size={15}/>Cadastrar</button>{msg&&<span className="text-sm text-gray-500 self-center">{msg}</span>}</form>
 <section className="bg-white border rounded-2xl overflow-auto mb-4"><table className="w-full text-sm"><thead><tr className="bg-gray-50"><th className="p-3 text-left">Nome</th><th>Codigo/link</th><th>Comissao</th><th>Status</th></tr></thead><tbody>{lista.map(a=><tr className="border-t" key={a.id}><td className="p-3 font-medium">{a.nome}</td><td><button className="inline-flex gap-1" onClick={()=>navigator.clipboard.writeText(`${location.origin}/registro?ref=${a.codigo}`)}>{a.codigo}<Copy size={13}/></button></td><td>{a.tipo_comissao==='fixa'?formatCurrency(a.comissao_fixa):`${a.comissao_percentual}%`}</td><td>{a.ativo?'Ativo':'Inativo'}</td></tr>)}</tbody></table></section>
 <section className="bg-white border rounded-2xl overflow-auto"><h2 className="font-semibold p-4">Extrato de indicacoes</h2><table className="w-full text-sm"><thead><tr className="bg-gray-50"><th className="p-3 text-left">Embaixador</th><th>Indicado</th><th>Conversao</th><th>Comissao</th><th>Pagamento</th></tr></thead><tbody>{indicacoes.map(i=><tr className="border-t" key={i.id}><td className="p-3">{i.embaixadores?.nome}</td><td>{i.nome_indicado||i.email_indicado||'Tenant vinculado'}</td><td>{i.status}</td><td>{formatCurrency(i.valor_comissao)}</td><td><select className="form-input" value={i.status_comissao} onChange={e=>status(i.id,e.target.value)}><option value="pendente">Pendente</option><option value="aprovada">Aprovada</option><option value="paga">Paga</option><option value="cancelada">Cancelada</option></select></td></tr>)}</tbody></table></section></div>
}
function Card({l,v}:{l:string,v:any}){return <div className="bg-white border rounded-2xl p-4"><div className="text-xs text-gray-500">{l}</div><div className="text-2xl font-bold">{v}</div></div>}

'use client'

import { useEffect, useState } from 'react'
import { Bike, ChefHat, Edit, Plus, Trash2, X } from 'lucide-react'

type Role='kitchen'|'motoboy'
type Member={id:string;nome:string;email:string;role:Role;ativo:boolean}
const roles=[{id:'kitchen' as Role,nome:'Cozinha',desc:'Acesso operacional aos pedidos em produção.',icon:ChefHat},{id:'motoboy' as Role,nome:'Motoboy',desc:'Acesso operacional às entregas atribuídas.',icon:Bike}]

export default function EquipePage(){const[members,setMembers]=useState<Member[]>([]);const[canManage,setCanManage]=useState(false);const[loading,setLoading]=useState(true);const[actionLoading,setActionLoading]=useState(false);const[editing,setEditing]=useState<Member|null>(null);const[open,setOpen]=useState(false);const[form,setForm]=useState<{nome:string;email:string;role:Role;ativo:boolean}>({nome:'',email:'',role:'kitchen',ativo:true});const[message,setMessage]=useState('')
async function load(){setLoading(true);const r=await fetch('/api/usuarios-loja');const b=await r.json();if(r.ok){setMembers(b.usuarios||[]);setCanManage(!!b.can_manage)}else setMessage(b.error);setLoading(false)}useEffect(()=>{load()},[])
function start(member?:Member){setEditing(member||null);setForm(member?{nome:member.nome,email:member.email,role:member.role,ativo:member.ativo}:{nome:'',email:'',role:'kitchen',ativo:true});setOpen(true)}
useEffect(()=>{if(!open)return;const key=(e:KeyboardEvent)=>{if(e.key==='Escape')setOpen(false)};document.addEventListener('keydown',key);requestAnimationFrame(()=>document.querySelector<HTMLElement>('.team-dialog input')?.focus());return()=>document.removeEventListener('keydown',key)},[open])
async function save(){setActionLoading(true);setMessage('');try{const r=await fetch('/api/usuarios-loja',{method:editing?'PATCH':'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(editing?{id:editing.id,...form}:form)});const b=await r.json();if(!r.ok){setMessage(b.error||'Não foi possível salvar.');return}setOpen(false);setMessage(editing?'Acesso atualizado.':'Convite enviado.');await load()}finally{setActionLoading(false)}}
async function toggle(member:Member){setActionLoading(true);const r=await fetch('/api/usuarios-loja',{method:'PATCH',headers:{'Content-Type':'application/json'},body:JSON.stringify({...member,ativo:!member.ativo})});const b=await r.json();if(!r.ok)setMessage(b.error||'Não foi possível alterar o acesso.');else await load();setActionLoading(false)}
async function remove(member:Member){if(!confirm(`Excluir o acesso de ${member.nome}?`))return;setActionLoading(true);const r=await fetch(`/api/usuarios-loja?id=${member.id}`,{method:'DELETE'});const b=await r.json();if(!r.ok)setMessage(b.error||'Não foi possível excluir o acesso.');else await load();setActionLoading(false)}
return <div className="space-y-5"><header className="flex justify-between items-start"><div><div className="eyebrow mb-2">Equipe</div><h1 className="text-3xl font-semibold">Acessos operacionais</h1><p className="hint mt-1">Somente Cozinha e Motoboy são disponibilizados nesta etapa.</p></div>{canManage&&<button className="btn-primary" onClick={()=>start()}><Plus size={16}/>Novo acesso</button>}</header>
<div className="grid md:grid-cols-2 gap-3">{roles.map(role=><div key={role.id} className="glass p-5"><role.icon size={20}/><h2 className="font-semibold mt-2">{role.nome}</h2><p className="hint text-sm">{role.desc}</p></div>)}</div>{message&&<p className="text-sm">{message}</p>}
<section className="glass p-5"><h2 className="font-semibold mb-3">Pessoas cadastradas</h2>{loading?<p className="hint">Carregando…</p>:members.length===0?<p className="hint">Nenhum acesso de Cozinha ou Motoboy cadastrado.</p>:<div className="space-y-2">{members.map(m=><div key={m.id} className="glass-soft p-4 flex items-center gap-3"><div className="flex-1"><b>{m.nome}</b><p className="hint text-xs">{m.email} · {roles.find(r=>r.id===m.role)?.nome} · {m.ativo?'Ativo':'Inativo'}</p></div>{canManage&&<><button className="btn-ghost" onClick={()=>toggle(m)}>{m.ativo?'Desativar':'Ativar'}</button><button className="btn-icon-round" onClick={()=>start(m)}><Edit size={14}/></button><button className="btn-icon-round" onClick={()=>remove(m)}><Trash2 size={14}/></button></>}</div>)}</div>}</section>
{open&&<div className="fixed inset-0 z-50 bg-black/50 flex items-center justify-center p-4" onMouseDown={e=>{if(e.target===e.currentTarget)setOpen(false)}}><div role="dialog" aria-modal="true" aria-labelledby="team-dialog-title" className="team-dialog glass-strong p-6 rounded-3xl w-full max-w-md max-h-[90vh] overflow-y-auto"><div className="flex justify-between"><h2 id="team-dialog-title" className="font-semibold">{editing?'Editar acesso':'Novo acesso'}</h2><button aria-label="Fechar" onClick={()=>setOpen(false)}><X size={18}/></button></div><div className="space-y-3 mt-4"><label>Nome<input value={form.nome} onChange={e=>setForm({...form,nome:e.target.value})}/></label><label>Email<input type="email" value={form.email} onChange={e=>setForm({...form,email:e.target.value})}/></label><label>Função<select value={form.role} onChange={e=>setForm({...form,role:e.target.value as Role})}>{roles.map(r=><option key={r.id} value={r.id}>{r.nome}</option>)}</select></label>{editing&&<label className="flex gap-2"><input type="checkbox" checked={form.ativo} onChange={e=>setForm({...form,ativo:e.target.checked})}/>Acesso ativo</label>}<button disabled={actionLoading} className="btn-primary w-full disabled:opacity-50" onClick={save}>{actionLoading?'Salvando…':'Salvar'}</button></div></div></div>}</div>}

'use client'

import { useEffect, useMemo, useState } from 'react'
import { createClient } from '@/lib/supabase/client'
import { ArrowLeftRight, BarChart3, CreditCard, FileText, Receipt, Truck, WalletCards } from 'lucide-react'
import { formatCurrency } from '@/lib/utils'

type Tab = 'overview'|'movements'|'cashflow'|'accounts'|'delivery'|'payments'|'reports'|'closing'
type Order = { id:string; created_at:string; valor_total:number; taxa_entrega:number; forma_pagamento:string; status:string }
type Expense = { id:string; nome:string; valor:number; dia_vencimento?:number|null; recorrencia?:string|null; created_at:string }
type StockMovement = { id:string; tipo:'entrada'|'saida'; quantidade:number; created_at:string; observacao?:string|null; insumos?:{nome:string;unidade:string;custo_unitario:number}|null }
type TenantFinance = { id:string; config:Record<string,unknown> }
const tabs = [
  ['overview','Visão geral',BarChart3],['movements','Entradas e saídas',ArrowLeftRight],['cashflow','Fluxo de caixa',WalletCards],['accounts','Contas a pagar/receber',Receipt],
  ['delivery','Taxas de entrega',Truck],['payments','Formas de pagamento',CreditCard],['reports','Relatórios',FileText],['closing','Fechamento de caixa',WalletCards],
] as const

export default function FinanceiroPage(){
  const supabase=useMemo(()=>createClient(),[]); const[tab,setTab]=useState<Tab>('overview'); const[orders,setOrders]=useState<Order[]>([]); const[expenses,setExpenses]=useState<Expense[]>([]); const[movements,setMovements]=useState<StockMovement[]>([]); const[tenant,setTenant]=useState<TenantFinance|null>(null); const[loading,setLoading]=useState(true)
  useEffect(()=>{(async()=>{try{const response=await fetch('/api/financeiro',{cache:'no-store'});const body=await response.json();if(!response.ok)throw new Error(body.error);setOrders(body.orders||[]);setExpenses(body.expenses||[]);setMovements(body.movements||[]);setTenant(body.tenant)}finally{setLoading(false)}})()},[])
  const validOrders=orders.filter(o=>o.status!=='cancelado');const realizedOrders=validOrders.filter(o=>o.status==='entregue');const pendingOrders=validOrders.filter(o=>o.status!=='entregue');const revenue=realizedOrders.reduce((s,o)=>s+Number(o.valor_total||0),0);const pendingRevenue=pendingOrders.reduce((s,o)=>s+Number(o.valor_total||0),0);const expenseTotal=expenses.reduce((s,e)=>s+Number(e.valor||0),0);const deliveryTotal=validOrders.reduce((s,o)=>s+Number(o.taxa_entrega||0),0);const balance=revenue-expenseTotal
  const days=useMemo(()=>{const result=new Map<string,number>();realizedOrders.forEach(o=>{const key=new Date(o.created_at).toLocaleDateString('pt-BR',{day:'2-digit',month:'2-digit'});result.set(key,(result.get(key)||0)+Number(o.valor_total||0))});return [...result].slice(0,7).reverse()},[realizedOrders]);const max=Math.max(1,...days.map(([,v])=>v))
  if(loading)return <div className="hint p-8">Carregando dados financeiros…</div>
  return <div className="space-y-5"><header><div className="eyebrow mb-2">Financeiro</div><h1 className="text-3xl font-semibold">Gestão financeira</h1><p className="hint mt-1">Pedidos, despesas, estoque e configurações reunidos em um só lugar.</p></header>
    <div className="grid grid-cols-2 md:grid-cols-4 gap-3">{tabs.map(([id,label,Icon])=><button key={id} onClick={()=>setTab(id)} className={`glass-soft min-h-24 rounded-2xl p-4 text-left transition ${tab===id?'ring-2 ring-green-500':''}`}><Icon size={18}/><span className="block text-sm font-semibold mt-2">{label}</span></button>)}</div>
    {tab==='overview'&&<p className="hint text-sm">Receita pendente: {formatCurrency(pendingRevenue)} em pedidos não cancelados e ainda não entregues.</p>}
    {tab==='overview'&&<><Metrics revenue={revenue} expenses={expenseTotal} balance={balance} orders={orders.length}/><section className="glass p-5"><h2 className="font-semibold mb-4">Vendas recentes por dia</h2>{days.length?<div className="h-48 flex items-end gap-3">{days.map(([day,value])=><div key={day} className="flex-1 text-center"><div className="bg-green-500 rounded-t-lg" style={{height:`${Math.max(8,value/max*150)}px`}} title={formatCurrency(value)}/><span className="text-xs hint">{day}</span></div>)}</div>:<Empty text="Ainda não há pedidos para formar o gráfico."/>}</section></>}
    {tab==='movements'&&<Movements rows={movements}/>} {tab==='cashflow'&&<CashFlow orders={validOrders} expenses={expenses}/>} {tab==='accounts'&&<Accounts orders={validOrders} expenses={expenses}/>} {tab==='delivery'&&<Delivery orders={validOrders} total={deliveryTotal}/>} {tab==='payments'&&<Payments tenant={tenant} onSaved={setTenant}/>} {tab==='reports'&&<Reports orders={realizedOrders} revenue={revenue} expenses={expenseTotal}/>} {tab==='closing'&&<Closing orders={validOrders} expenses={expenses}/>} </div>
}
function Metrics({revenue,expenses,balance,orders}:any){return <div className="grid md:grid-cols-4 gap-3">{[['Receita realizada (entregues)',revenue],['Despesas cadastradas',expenses],['Saldo realizado',balance],['Pedidos consultados',orders]].map(([l,v],i)=><div key={String(l)} className="glass p-4"><p className="hint text-xs">{l}</p><p className="text-xl font-bold mt-1">{i===3?String(v):formatCurrency(Number(v))}</p></div>)}</div>}
const Empty=({text}:{text:string})=><p className="hint text-sm py-8 text-center">{text}</p>
function Movements({rows}:{rows:any[]}){return <section className="glass p-5"><h2 className="font-semibold mb-3">Movimentações de insumos</h2>{rows.length?rows.map(r=><div key={r.id} className="border-b py-3 flex justify-between"><div><b>{r.insumos?.nome||'Insumo'}</b><p className="hint text-xs">{new Date(r.created_at).toLocaleString('pt-BR')} · {r.observacao||'Sem observação'}</p></div><span className={r.tipo==='entrada'?'text-green-700':'text-red-700'}>{r.tipo==='entrada'?'+':'-'}{Number(r.quantidade)} {r.insumos?.unidade}</span></div>):<Empty text="Nenhuma entrada ou saída de insumo registrada."/>}</section>}
function CashFlow({orders,expenses}:{orders:Order[];expenses:any[]}){const rows=[...orders.map(o=>({date:o.created_at,label:`Pedido #${o.id.slice(0,8)}`,value:Number(o.valor_total),kind:'entrada'})),...expenses.map(e=>({date:e.created_at,label:e.nome,value:-Number(e.valor),kind:'saída'}))].sort((a,b)=>+new Date(b.date)-+new Date(a.date));return <section className="glass p-5"><h2 className="font-semibold mb-3">Fluxo registrado</h2>{rows.length?rows.slice(0,100).map((r,i)=><div key={`${r.kind}-${i}`} className="flex justify-between border-b py-3"><span>{r.label}<small className="block hint">{new Date(r.date).toLocaleDateString('pt-BR')}</small></span><b className={r.value>=0?'text-green-700':'text-red-700'}>{formatCurrency(r.value)}</b></div>):<Empty text="Sem lançamentos para exibir."/>}</section>}
function Accounts({orders,expenses}:{orders:Order[];expenses:any[]}){return <div className="grid md:grid-cols-2 gap-4"><section className="glass p-5"><h2 className="font-semibold">Contas a pagar</h2>{expenses.length?expenses.map(e=><p key={e.id} className="border-b py-3 flex justify-between"><span>{e.nome}<small className="block hint">dia {e.dia_vencimento||'—'} · {e.recorrencia}</small></span><b>{formatCurrency(Number(e.valor))}</b></p>):<Empty text="Nenhuma despesa cadastrada."/>}</section><section className="glass p-5"><h2 className="font-semibold">Valores de pedidos</h2><p className="hint text-xs mb-2">Pedidos registrados; conciliação bancária não é automática.</p>{orders.length?orders.slice(0,30).map(o=><p key={o.id} className="border-b py-3 flex justify-between"><span>#{o.id.slice(0,8)}<small className="block hint">{o.status}</small></span><b>{formatCurrency(Number(o.valor_total))}</b></p>):<Empty text="Nenhum pedido registrado."/>}</section></div>}
function Delivery({orders,total}:{orders:Order[];total:number}){const charged=orders.filter(o=>Number(o.taxa_entrega)>0);return <section className="glass p-5"><h2 className="font-semibold">Taxas de entrega</h2><p className="text-2xl font-bold my-3">{formatCurrency(total)}</p>{charged.length?charged.slice(0,50).map(o=><p key={o.id} className="flex justify-between border-b py-2"><span>Pedido #{o.id.slice(0,8)}</span><b>{formatCurrency(Number(o.taxa_entrega))}</b></p>):<Empty text="Nenhuma taxa cobrada nos pedidos consultados."/>}</section>}
function Payments({tenant,onSaved}:{tenant:any;onSaved:(v:any)=>void}){const initial=tenant?.config?.formas_pagamento_aceitas||{};const[values,setValues]=useState<Record<string,boolean>>(initial);async function save(){const response=await fetch('/api/financeiro',{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify({formas:values})});const body=await response.json();if(response.ok){onSaved({...tenant,config:body.config});alert('Formas de pagamento salvas.')}else alert(body.error||'Não foi possível salvar.')}return <section className="glass p-5"><h2 className="font-semibold mb-3">Formas aceitas no cardápio</h2>{[['dinheiro','Dinheiro'],['pix','Pix'],['cartao_credito','Cartão de crédito'],['cartao_debito','Cartão de débito']].map(([id,label])=><label key={id} className="flex justify-between border-b py-3"><span>{label}</span><input type="checkbox" checked={!!values[id]} onChange={()=>setValues(v=>({...v,[id]:!v[id]}))}/></label>)}<button onClick={save} className="btn-primary mt-4">Salvar</button></section>}
function Reports({orders,revenue,expenses}:any){const byPayment=orders.reduce((a:any,o:Order)=>{a[o.forma_pagamento||'não informado']=(a[o.forma_pagamento||'não informado']||0)+Number(o.valor_total);return a},{});return <section className="glass p-5"><h2 className="font-semibold mb-3">Resumo do período disponível</h2><Metrics revenue={revenue} expenses={expenses} balance={revenue-expenses} orders={orders.length}/><div className="mt-4">{Object.entries(byPayment).map(([k,v])=><p key={k} className="flex justify-between border-b py-2"><span>{k.replaceAll('_',' ')}</span><b>{formatCurrency(Number(v))}</b></p>)}</div></section>}
function Closing({orders,expenses}:{orders:Order[];expenses:any[]}){const today=new Date().toDateString();const dayOrders=orders.filter(o=>new Date(o.created_at).toDateString()===today&&o.status!=='cancelado');const entries=dayOrders.reduce((s,o)=>s+Number(o.valor_total),0);const out=expenses.filter(e=>new Date(e.created_at).toDateString()===today).reduce((s,e)=>s+Number(e.valor),0);return <section className="glass p-5"><h2 className="font-semibold">Fechamento de hoje</h2><p className="hint text-xs mb-4">Consolidação dos registros do sistema; confira com caixa e extratos.</p><Metrics revenue={entries} expenses={out} balance={entries-out} orders={dayOrders.length}/></section>}

