'use client'

import { useState, useEffect } from 'react'
import { createClient } from '@/lib/supabase/client'
import { activeTenantId } from '@/lib/active-tenant-client'
import { CreditCard, Check, Clock, AlertTriangle, Sparkles, Loader2 } from 'lucide-react'
import { formatCurrency } from '@/lib/utils'
import { PixQrCodeModal } from '@/components/pix-qrcode-modal'

type Mensalidade = {
  id: string
  competencia: string
  valor: number
  vencimento: string
  status: 'pago' | 'pendente' | 'vencido'
  pago_em: string | null
}

export default function MensalidadePage() {
  const [mensalidades, setMensalidades] = useState<Mensalidade[]>([])
  const [loading, setLoading] = useState(true)
  const [pixModal, setPixModal] = useState<{ txid: string; valor: number; brCode: string; qrCodeBase64?: string } | null>(null)
  const supabase = createClient()

  useEffect(() => { load() }, [])

  const load = async () => {
    setLoading(true)
    try {
      const { data: { user } } = await supabase.auth.getUser()
      if (!user) return
      const tid = await activeTenantId()
      if (!tid) return

      // Garante mensalidades geradas pra esse tenant
      await fetch('/api/mensalidades/gerar', { method: 'POST' })

      const { data } = await supabase
        .from('mensalidades')
        .select('*')
        .eq('tenant_id', tid)
        .order('ano', { ascending: false })
        .order('mes', { ascending: false })

      // Mapear pro tipo da UI
      const mapped: Mensalidade[] = (data || []).map((m) => ({
        id: m.id,
        competencia: `${m.ano}-${String(m.mes).padStart(2, '0')}`,
        valor: Number(m.valor),
        vencimento: m.data_vencimento,
        status: m.status,
        pago_em: m.data_pagamento,
      }))
      setMensalidades(mapped)
    } catch (e) {
      console.error('Erro ao carregar mensalidades:', e)
    } finally {
      setLoading(false)
    }
  }

  const handlePagar = async (m: Mensalidade) => {
    if (m.status === 'pago') return
    try {
      const res = await fetch('/api/pix/gerar', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ mensalidade_id: m.id }),
      })
      const data = await res.json()
      if (!res.ok) throw new Error(data.error || 'Erro ao gerar PIX')
      setPixModal({ txid: data.txid, valor: m.valor, brCode: data.br_code, qrCodeBase64: data.qr_code_base64 })
    } catch (e: any) {
      alert(e.message || 'Erro ao gerar PIX')
    }
  }

  const formatMes = (comp: string) => {
    const [ano, mes] = comp.split('-')
    const meses = ['Janeiro', 'Fevereiro', 'Março', 'Abril', 'Maio', 'Junho', 'Julho', 'Agosto', 'Setembro', 'Outubro', 'Novembro', 'Dezembro']
    return `${meses[parseInt(mes) - 1]} ${ano}`
  }
  const formatDate = (iso: string) => new Date(iso).toLocaleDateString('pt-BR')

  const totalPago = mensalidades.filter(m => m.status === 'pago').reduce((s, m) => s + m.valor, 0)
  const totalAberto = mensalidades.filter(m => m.status !== 'pago').reduce((s, m) => s + m.valor, 0)

  if (loading) {
    return (
      <div className="text-center py-12">
        <Loader2 className="mx-auto animate-spin mb-3" size={32} style={{ color: 'var(--green)' }} />
        <p className="hint">Carregando mensalidades...</p>
      </div>
    )
  }

  return (
    <div>
      <div className="glass-iridescent px-7 py-7 mb-5 relative">
        <div className="relative z-10 flex flex-wrap items-end justify-between gap-4">
          <div>
            <div className="eyebrow mb-2 flex items-center gap-1.5">
              <Sparkles size={11} />
              Financeiro
            </div>
            <h1 className="text-3xl md:text-4xl font-semibold tracking-tight" style={{ color: 'var(--ink)' }}>
              Mensalidades
            </h1>
            <p className="hint mt-2">Histórico e pagamentos da sua assinatura</p>
          </div>
          <div className="flex gap-3">
            <div className="glass-soft px-4 py-2.5 text-center">
              <div className="hint text-xs">Pago</div>
              <div className="text-sm font-semibold gradient-text-teal">{formatCurrency(totalPago)}</div>
            </div>
            <div className="glass-soft px-4 py-2.5 text-center">
              <div className="hint text-xs">Em aberto</div>
              <div className="text-sm font-semibold" style={{ color: '#BE185D' }}>{formatCurrency(totalAberto)}</div>
            </div>
          </div>
        </div>
      </div>

      <div className="glass p-6">
        <div className="eyebrow mb-4">Histórico</div>
        <div className="flex flex-col gap-2">
          {mensalidades.map((m) => {
            const isPago = m.status === 'pago'
            const isVencido = m.status === 'vencido'

            return (
              <div
                key={m.id}
                className="glass-soft p-4 flex items-center gap-4"
                style={isVencido ? { background: 'rgba(239,68,68,.06)', borderColor: 'rgba(239,68,68,.25)' } : undefined}
              >
                <div
                  className="size-11 rounded-xl flex items-center justify-center"
                  style={{
                    background: isPago ? 'rgba(16,185,129,.14)' : isVencido ? 'rgba(239,68,68,.14)' : 'rgba(245,158,11,.14)',
                  }}
                >
                  {isPago ? <Check size={18} style={{ color: '#047857' }} strokeWidth={2.5} /> :
                    isVencido ? <AlertTriangle size={18} style={{ color: '#B91C1C' }} strokeWidth={2.5} /> :
                      <Clock size={18} style={{ color: '#92400E' }} strokeWidth={2.5} />}
                </div>

                <div className="flex-1 min-w-0">
                  <div className="flex items-center gap-2 mb-0.5">
                    <div className="text-sm font-semibold" style={{ color: 'var(--ink)' }}>
                      {formatMes(m.competencia)}
                    </div>
                    {isPago && <span className="chip chip--positive">Pago</span>}
                    {isVencido && <span className="chip chip--negative">Vencido</span>}
                    {!isPago && !isVencido && <span className="chip chip--warn">Pendente</span>}
                  </div>
                  <div className="hint text-xs">
                    Vencimento: {formatDate(m.vencimento)}
                    {isPago && m.pago_em && ` • Pago em ${formatDate(m.pago_em)}`}
                  </div>
                </div>

                <div className="text-right">
                  <div className="text-base font-semibold tabular-nums mb-2" style={{ color: 'var(--ink)' }}>
                    {formatCurrency(m.valor)}
                  </div>
                  {!isPago && (
                    <button
                      onClick={() => handlePagar(m)}
                      className="btn-primary text-xs"
                      style={{ padding: '0.4rem 0.85rem', fontSize: '0.75rem' }}
                    >
                      <CreditCard size={12} />
                      Pagar com PIX
                    </button>
                  )}
                </div>
              </div>
            )
          })}
        </div>

        {mensalidades.length === 0 && (
          <div className="text-center py-8 hint">
            Nenhuma mensalidade registrada
          </div>
        )}
      </div>

      {pixModal && (
        <PixQrCodeModal
          onClose={() => setPixModal(null)}
          valor={pixModal.valor}
          brCode={pixModal.brCode}
          qrCodeBase64={pixModal.qrCodeBase64 || ''}
          txid={pixModal.txid}
          expiracao={new Date(Date.now() + 24 * 60 * 60 * 1000).toISOString()}
        />
      )}
    </div>
  )
}

'use client'

import { useState, useEffect } from 'react'
import { Plus, Trash2, Utensils } from 'lucide-react'

export default function MesasPage() {
  const [mesas, setMesas] = useState<any[]>([])
  const [showForm, setShowForm] = useState(false)
  const [form, setForm] = useState({ numero: '', nome: '', capacidade: '4' })

  useEffect(() => { carregar() }, [])

  async function carregar() {
    const res = await fetch('/api/mesas')
    const data = await res.json()
    setMesas(data.mesas || [])
  }

  async function salvar() {
    await fetch('/api/mesas', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        numero: parseInt(form.numero) || 0,
        nome: form.nome || `Mesa ${form.numero}`,
        capacidade: parseInt(form.capacidade) || 4,
      })
    })
    setShowForm(false)
    setForm({ numero: '', nome: '', capacidade: '4' })
    carregar()
  }

  async function remover(id: string) {
    if (!confirm('Remover mesa?')) return
    await fetch(`/api/mesas?id=${id}`, { method: 'DELETE' })
    carregar()
  }

  return (
    <div className="space-y-6">
      <div className="flex items-center justify-between">
        <div>
          <div className="eyebrow mb-2">Salão</div>
          <h1 className="text-2xl font-semibold">Mesas</h1>
        </div>
        <button onClick={() => setShowForm(!showForm)} className="btn-primary">
          <Plus size={16} /> Nova mesa
        </button>
      </div>

      {showForm && (
        <div className="glass-soft p-6 rounded-2xl space-y-3">
          <div className="grid grid-cols-3 gap-2">
            <input type="number" placeholder="Nº" value={form.numero} onChange={e => setForm({...form, numero: e.target.value})} className="px-3 py-2 border rounded-xl" />
            <input placeholder="Nome" value={form.nome} onChange={e => setForm({...form, nome: e.target.value})} className="px-3 py-2 border rounded-xl" />
            <input type="number" placeholder="Capacidade" value={form.capacidade} onChange={e => setForm({...form, capacidade: e.target.value})} className="px-3 py-2 border rounded-xl" />
          </div>
          <button onClick={salvar} className="btn-primary">Adicionar mesa</button>
        </div>
      )}

      <div className="grid grid-cols-2 md:grid-cols-4 gap-3">
        {mesas.length === 0 ? (
          <div className="col-span-full glass-soft p-12 text-center rounded-2xl">
            <Utensils className="w-12 h-12 mx-auto mb-3 text-gray-300" />
            <p className="text-gray-500">Nenhuma mesa cadastrada</p>
          </div>
        ) : mesas.map(m => (
          <div key={m.id} className="glass-soft p-4 rounded-2xl text-center">
            <div className="text-3xl font-bold mb-1">{m.numero}</div>
            <p className="text-sm text-gray-600">{m.nome}</p>
            <p className="text-xs text-gray-400">Capacidade: {m.capacidade}</p>
            <span className={`mt-2 inline-block px-2 py-0.5 rounded-full text-xs ${
              m.status === 'livre' ? 'bg-green-100 text-green-700' :
              m.status === 'ocupada' ? 'bg-red-100 text-red-700' :
              'bg-yellow-100 text-yellow-700'
            }`}>{m.status}</span>
            <button onClick={() => remover(m.id)} className="block mx-auto mt-2 text-red-500 text-xs"><Trash2 size={14} /></button>
          </div>
        ))}
      </div>
    </div>
  )
}

﻿'use client'

import { useState, useEffect } from 'react'
import { createClient } from '@/lib/supabase/client'
import { activeTenantId } from '@/lib/active-tenant-client'
import {
  Plus, Edit, Trash2, Save, X, Bike, Phone,
  TrendingUp, DollarSign, AlertCircle, Award
} from 'lucide-react'
import { formatCurrency } from '@/lib/utils'

type Motoboy = {
  id: string
  nome: string
  telefone: string
  veiculo: string | null
  placa: string | null
  ativo: boolean
  tipo_comissao: 'percentual' | 'fixa'
  comissao_percent: number
  comissao_fixa: number
  total_entregas: number
  total_ganho: number
  observacoes: string | null
}

export default function MotoboysPage() {
  const [motoboys, setMotoboys] = useState<Motoboy[]>([])
  const [loading, setLoading] = useState(true)
  const [showModal, setShowModal] = useState(false)
  const [editing, setEditing] = useState<Motoboy | null>(null)
  const supabase = createClient()

  useEffect(() => { loadData() }, [])

  const loadData = async () => {
    const tenantId = await activeTenantId()
    if (!tenantId) { setLoading(false); return }

    const { data, error } = await supabase
      .from('motoboys')
      .select('*')
      .eq('tenant_id', tenantId)
      .order('nome')
    if (!error) setMotoboys(data || [])
    setLoading(false)
  }

  const deletar = async (id: string) => {
    if (!confirm('Tem certeza? Se este motoboy estiver atribuído a pedidos, o vínculo será removido.')) return
    await supabase.from('motoboys').delete().eq('id', id)
    loadData()
  }

  const abrirModal = (m?: Motoboy) => {
    setEditing(m || null)
    setShowModal(true)
  }

  // Stats
  const ativos = motoboys.filter((m) => m.ativo)
  const totalEntregas = motoboys.reduce((acc, m) => acc + (m.total_entregas || 0), 0)
  const totalGanho = motoboys.reduce((acc, m) => acc + Number(m.total_ganho || 0), 0)
  const top = [...motoboys]
    .filter((m) => m.ativo && m.total_entregas > 0)
    .sort((a, b) => b.total_entregas - a.total_entregas)
    .slice(0, 3)

  return (
    <div>
      <div className="bg-white rounded-2xl border p-5 mb-4 flex items-center justify-between gap-3" style={{ borderColor: '#E5E7EB' }}>
        <div>
          <div className="text-xs text-gray-500 mb-1 flex items-center gap-1.5">
            <Bike size={11} /> Logística
          </div>
          <h1 className="text-3xl font-bold tracking-tight text-gray-900">Motoboys</h1>
          <p className="text-sm text-gray-500 mt-1">
            Entregadores próprios da loja. Configure comissão e acompanhe entregas.
          </p>
        </div>
        <button onClick={() => abrirModal()} className="btn-primary">
          <Plus size={14} />
          Novo motoboy
        </button>
      </div>

      {/* Cards métrica */}
      <div className="grid grid-cols-2 md:grid-cols-4 gap-3 mb-4">
        <MetricCard label="Motoboys ativos" value={ativos.length} icon={Bike} color="#3B82F6" />
        <MetricCard label="Total entregas" value={totalEntregas} icon={TrendingUp} color="#16A34A" />
        <MetricCard label="Total pago (comissões)" value={formatCurrency(totalGanho)} icon={DollarSign} color="#A855F7" />
        <div className="bg-white rounded-2xl border p-4" style={{ borderColor: '#E5E7EB' }}>
          <div className="flex items-center gap-2 mb-2">
            <div className="size-8 rounded-lg flex items-center justify-center" style={{ background: '#FEF9C315' }}>
              <Award size={16} style={{ color: '#EAB308' }} />
            </div>
            <div className="text-xs text-gray-500">Top entregadores</div>
          </div>
          <div className="space-y-1">
            {top.length === 0 ? (
              <div className="text-xs text-gray-400">—</div>
            ) : top.map((m, i) => (
              <div key={m.id} className="flex items-center justify-between text-sm">
                <span className="text-gray-700 truncate">
                  {i + 1}. {m.nome}
                </span>
                <span className="text-gray-500 text-xs">{m.total_entregas}×</span>
              </div>
            ))}
          </div>
        </div>
      </div>

      {/* Lista */}
      <div className="bg-white rounded-2xl border overflow-hidden" style={{ borderColor: '#E5E7EB' }}>
        {loading ? (
          <div className="text-center py-12 text-gray-500">Carregando...</div>
        ) : motoboys.length === 0 ? (
          <div className="text-center py-12">
            <Bike size={32} className="mx-auto text-gray-300 mb-3" />
            <div className="text-sm text-gray-500">
              Nenhum motoboy cadastrado ainda. Clique em "Novo motoboy" pra começar.
            </div>
          </div>
        ) : (
          <table className="w-full">
            <thead className="bg-gray-50 text-xs text-gray-500 uppercase">
              <tr>
                <th className="text-left px-4 py-3">Motoboy</th>
                <th className="text-left px-4 py-3">Telefone</th>
                <th className="text-left px-4 py-3">Veículo</th>
                <th className="text-left px-4 py-3">Comissão</th>
                <th className="text-right px-4 py-3">Entregas</th>
                <th className="text-right px-4 py-3">Total ganho</th>
                <th className="text-center px-4 py-3">Status</th>
                <th className="text-left px-4 py-3">Ações</th>
              </tr>
            </thead>
            <tbody>
              {motoboys.map((m) => (
                <tr key={m.id} className="border-t" style={{ borderColor: '#F3F4F6' }}>
                  <td className="px-4 py-3">
                    <div className="font-medium text-gray-900">{m.nome}</div>
                    {!m.ativo && <span className="text-xs text-gray-400">(Inativo)</span>}
                  </td>
                  <td className="px-4 py-3 text-sm">
                    <a
                      href={`https://wa.me/55${(m.telefone || '').replace(/\D/g, '')}`}
                      target="_blank"
                      rel="noopener noreferrer"
                      className="text-gray-700 hover:text-green-600 flex items-center gap-1"
                    >
                      <Phone size={11} />
                      {m.telefone}
                    </a>
                  </td>
                  <td className="px-4 py-3 text-sm text-gray-700">
                    {m.veiculo || <span className="text-gray-400">—</span>}
                    {m.placa && <span className="text-xs text-gray-500 ml-1">({m.placa})</span>}
                  </td>
                  <td className="px-4 py-3 text-sm">
                    {m.tipo_comissao === 'fixa'
                      ? `${formatCurrency(Number(m.comissao_fixa))}/entrega`
                      : `${Number(m.comissao_percent).toFixed(1)}% por entrega`}
                  </td>
                  <td className="px-4 py-3 text-right">
                    <div className="text-sm font-semibold text-gray-900">{m.total_entregas || 0}</div>
                  </td>
                  <td className="px-4 py-3 text-right">
                    <div className="text-sm font-semibold text-green-700">
                      {formatCurrency(Number(m.total_ganho) || 0)}
                    </div>
                  </td>
                  <td className="px-4 py-3 text-center">
                    <Switch checked={m.ativo} onChange={async (v) => {
                      await supabase.from('motoboys').update({ ativo: v }).eq('id', m.id)
                      loadData()
                    }} />
                  </td>
                  <td className="px-4 py-3">
                    <div className="flex items-center gap-1">
                      <button onClick={() => abrirModal(m)} className="size-7 rounded-lg hover:bg-gray-100 flex items-center justify-center text-gray-600">
                        <Edit size={12} />
                      </button>
                      <button onClick={() => deletar(m.id)} className="size-7 rounded-lg hover:bg-red-50 flex items-center justify-center text-red-600">
                        <Trash2 size={12} />
                      </button>
                    </div>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        )}
      </div>

      {showModal && (
        <MotoboyModal
          motoboy={editing}
          onClose={() => { setShowModal(false); setEditing(null) }}
          onSaved={loadData}
        />
      )}
    </div>
  )
}

function MotoboyModal({ motoboy, onClose, onSaved }: any) {
  const [form, setForm] = useState({
    nome: motoboy?.nome || '',
    telefone: motoboy?.telefone || '',
    veiculo: motoboy?.veiculo || '',
    placa: motoboy?.placa || '',
    tipo_comissao: motoboy?.tipo_comissao || 'percentual',
    comissao_percent: motoboy?.comissao_percent != null ? String(motoboy.comissao_percent) : '5',
    comissao_fixa: motoboy?.comissao_fixa != null ? String(motoboy.comissao_fixa) : '',
    ativo: motoboy?.ativo ?? true,
    observacoes: motoboy?.observacoes || '',
  })
  const [salvando, setSalvando] = useState(false)
  const supabase = createClient()

  const submit = async () => {
    if (!form.nome.trim() || !form.telefone.trim()) return
    setSalvando(true)
    const tenantId = await activeTenantId()
    if (!tenantId) { setSalvando(false); return }

    const payload: any = {
      nome: form.nome,
      telefone: form.telefone.replace(/\D/g, ''),
      veiculo: form.veiculo || null,
      placa: form.placa || null,
      tipo_comissao: form.tipo_comissao,
      comissao_percent: parseFloat(form.comissao_percent) || 0,
      comissao_fixa: parseFloat(form.comissao_fixa) || 0,
      ativo: form.ativo,
      observacoes: form.observacoes || null,
    }

    if (motoboy) {
      await supabase.from('motoboys').update(payload).eq('id', motoboy.id)
    } else {
      await supabase.from('motoboys').insert({
        ...payload,
        tenant_id: tenantId,
      })
    }
    setSalvando(false)
    onSaved()
    onClose()
  }

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center p-4" style={{ background: 'rgba(0,0,0,.5)', backdropFilter: 'blur(4px)' }}>
      <div className="bg-white rounded-2xl shadow-2xl w-full max-w-md">
        <div className="flex items-center justify-between px-6 py-4 border-b" style={{ borderColor: '#E5E7EB' }}>
          <h1 className="text-lg font-semibold text-gray-900">{motoboy ? 'Editar motoboy' : 'Novo motoboy'}</h1>
          <button onClick={onClose} className="text-gray-400 hover:text-gray-700 p-1"><X size={20} /></button>
        </div>
        <div className="px-6 py-5 space-y-4 bg-gray-50">
          <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
            <Field label="Nome" required>
              <input value={form.nome} onChange={(e) => setForm({ ...form, nome: e.target.value })} className="form-input" placeholder="Ex: João Silva" autoFocus />
            </Field>
            <Field label="Telefone" required>
              <input value={form.telefone} onChange={(e) => setForm({ ...form, telefone: e.target.value })} className="form-input" placeholder="(47) 99999-9999" />
            </Field>
            <Field label="Veículo">
              <input value={form.veiculo} onChange={(e) => setForm({ ...form, veiculo: e.target.value })} className="form-input" placeholder="Ex: Honda CG 160" />
            </Field>
            <Field label="Placa">
              <input value={form.placa} onChange={(e) => setForm({ ...form, placa: e.target.value })} className="form-input" placeholder="ABC-1234" />
            </Field>
          </div>

          <Field label="Tipo de comissão">
            <div className="flex gap-2">
              <button
                type="button"
                onClick={() => setForm({ ...form, tipo_comissao: 'percentual' })}
                className="flex-1 px-4 py-2.5 rounded-xl text-sm font-medium transition"
                style={
                  form.tipo_comissao === 'percentual'
                    ? { background: 'var(--green)', color: 'white' }
                    : { background: 'white', color: '#374151', border: '1px solid #D1D5DB' }
                }
              >
                % por entrega
              </button>
              <button
                type="button"
                onClick={() => setForm({ ...form, tipo_comissao: 'fixa' })}
                className="flex-1 px-4 py-2.5 rounded-xl text-sm font-medium transition"
                style={
                  form.tipo_comissao === 'fixa'
                    ? { background: 'var(--green)', color: 'white' }
                    : { background: 'white', color: '#374151', border: '1px solid #D1D5DB' }
                }
              >
                R$ fixo por entrega
              </button>
            </div>
          </Field>

          {form.tipo_comissao === 'percentual' ? (
            <Field label="Comissão (%)" hint="sobre o valor da entrega">
              <input
                type="number"
                step="0.1"
                value={form.comissao_percent}
                onChange={(e) => setForm({ ...form, comissao_percent: e.target.value })}
                className="form-input max-w-[200px]"
                placeholder="5"
              />
            </Field>
          ) : (
            <Field label="Comissão fixa (R$)">
              <input
                type="number"
                step="0.01"
                value={form.comissao_fixa}
                onChange={(e) => setForm({ ...form, comissao_fixa: e.target.value })}
                className="form-input max-w-[200px]"
                placeholder="3.50"
              />
            </Field>
          )}

          <Field label="Observações" hint="(opcional)">
            <textarea
              value={form.observacoes}
              onChange={(e) => setForm({ ...form, observacoes: e.target.value })}
              className="form-input"
              rows={2}
              placeholder="Ex: Só atende zona norte"
            />
          </Field>

          <label className="flex items-center gap-3 cursor-pointer">
            <input
              type="checkbox"
              checked={form.ativo}
              onChange={(e) => setForm({ ...form, ativo: e.target.checked })}
              className="size-4 rounded border-gray-300 text-green-600"
            />
            <span className="text-sm text-gray-900">Ativo</span>
          </label>
        </div>
        <div className="flex items-center justify-end gap-3 px-6 py-4 border-t bg-white" style={{ borderColor: '#E5E7EB' }}>
          <button onClick={onClose} className="btn-ghost" disabled={salvando}>Cancelar</button>
          <button onClick={submit} className="btn-primary" disabled={salvando || !form.nome.trim() || !form.telefone.trim()}>
            <Save size={14} />
            {salvando ? 'Salvando...' : motoboy ? 'Salvar' : 'Criar motoboy'}
          </button>
        </div>
      </div>
    </div>
  )
}

function MetricCard({ label, value, icon: Icon, color }: any) {
  return (
    <div className="bg-white rounded-2xl border p-4" style={{ borderColor: '#E5E7EB' }}>
      <div className="flex items-center gap-2 mb-2">
        <div className="size-8 rounded-lg flex items-center justify-center" style={{ background: `${color}15` }}>
          <Icon size={16} style={{ color }} />
        </div>
        <div className="text-xs text-gray-500">{label}</div>
      </div>
      <div className="text-2xl font-bold text-gray-900">{value}</div>
    </div>
  )
}

function Field({ label, required, hint, children }: any) {
  return (
    <div>
      <label className="block text-sm font-medium text-gray-700 mb-1.5">
        {label}
        {required && <span className="text-red-500 ml-0.5">*</span>}
        {hint && <span className="text-gray-400 font-normal ml-1">{hint}</span>}
      </label>
      {children}
    </div>
  )
}

function Switch({ checked, onChange }: { checked: boolean; onChange: (v: boolean) => void }) {
  return (
    <button
      type="button"
      onClick={() => onChange(!checked)}
      className="w-10 h-5 rounded-full transition relative"
      style={{ background: checked ? 'var(--green)' : '#D1D5DB' }}
    >
      <div
        className="size-4 rounded-full bg-white absolute top-0.5 transition-all shadow"
        style={{ left: checked ? '20px' : '2px' }}
      />
    </button>
  )
}

﻿'use client'

import { useState, useEffect } from 'react'
import { useRouter } from 'next/navigation'
import { createClient } from '@/lib/supabase/client'
import { activeTenantId } from '@/lib/active-tenant-client'
import { ArrowLeft, ShoppingBag, MapPin, CreditCard, Plus, Trash2, Check, MessageCircle } from 'lucide-react'
import { formatCurrency } from '@/lib/utils'

interface Cliente {
  id: string
  nome: string
  telefone: string
  endereco?: string
  bairro?: string
}

interface Produto {
  id: string
  nome: string
  preco: number
  imagem_url?: string
}

interface ItemPedido {
  produto_id: string
  nome: string
  quantidade: number
  valor_unitario: number
}

export default function NovoPedidoPage() {
  const router = useRouter()
  const supabase = createClient()

  const [loading, setLoading] = useState(false)
  const [clientes, setClientes] = useState<Cliente[]>([])
  const [produtos, setProdutos] = useState<Produto[]>([])
  const [itens, setItens] = useState<ItemPedido[]>([])
  const [formaPagamento, setFormaPagamento] = useState<string>('dinheiro')
  const [valorPago, setValorPago] = useState('')
  const [troco, setTroco] = useState(0)
  const [observacoes, setObservacoes] = useState('')
  const [taxaEntrega, setTaxaEntrega] = useState(0)
  const [clienteSelecionado, setClienteSelecionado] = useState<Cliente | null>(null)
  const [enderecoEntrega, setEnderecoEntrega] = useState('')
  const [pedidoCriado, setPedidoCriado] = useState<any>(null)
  const [whatsappUrl, setWhatsappUrl] = useState('')
  const [whatsappMsg, setWhatsappMsg] = useState('')

  // Busca clientes e produtos ao carregar
  useEffect(() => {
    loadDados()
  }, [])

  // Calcula troco automaticamente
  useEffect(() => {
    const total = calcularTotal()
    const pago = parseFloat(valorPago) || 0
    if (pago > total) {
      setTroco(pago - total)
    } else {
      setTroco(0)
    }
  }, [valorPago, itens, taxaEntrega])

  const loadDados = async () => {
    const tenantId = await activeTenantId()
    if (!tenantId) return

    // Carregar clientes
    const { data: clientesData } = await supabase
      .from('clientes')
      .select('*')
      .eq('tenant_id', tenantId)
      .order('nome')

    // Carregar produtos
    const { data: produtosData } = await supabase
      .from('produtos')
      .select('id, nome, preco, imagem_url')
      .eq('tenant_id', tenantId)
      .eq('ativo', true)
      .order('nome')

    setClientes(clientesData || [])
    setProdutos(produtosData || [])
  }

  const adicionarItem = (produto: Produto) => {
    const existente = itens.find(i => i.produto_id === produto.id)
    if (existente) {
      setItens(itens.map(i =>
        i.produto_id === produto.id
          ? { ...i, quantidade: i.quantidade + 1 }
          : i
      ))
    } else {
      setItens([...itens, {
        produto_id: produto.id,
        nome: produto.nome,
        quantidade: 1,
        valor_unitario: produto.preco,
      }])
    }
  }

  const atualizarQuantidade = (produtoId: string, quantidade: number) => {
    if (quantidade <= 0) {
      setItens(itens.filter(i => i.produto_id !== produtoId))
    } else {
      setItens(itens.map(i =>
        i.produto_id === produtoId ? { ...i, quantidade } : i
      ))
    }
  }

  const removerItem = (produtoId: string) => {
    setItens(itens.filter(i => i.produto_id !== produtoId))
  }

  const calcularTotal = () => {
    const subtotal = itens.reduce((acc, item) => acc + (item.valor_unitario * item.quantidade), 0)
    return subtotal + taxaEntrega
  }

  const criarPedido = async () => {
    if (itens.length === 0) {
      alert('Adicione pelo menos um item ao pedido')
      return
    }

    if (!clienteSelecionado) {
      alert('Selecione um cliente')
      return
    }

    setLoading(true)

    try {
      const tenantId = await activeTenantId()
      if (!tenantId) throw new Error('Não autenticado')

      const total = calcularTotal()
      const pago = parseFloat(valorPago) || total

      // Criar pedido
      const { data: pedido, error: pedidoError } = await supabase
        .from('pedidos')
        .insert({
          tenant_id: tenantId,
          cliente_id: clienteSelecionado.id,
          status: 'novo',
          valor_total: total,
          taxa_entrega: taxaEntrega,
          forma_pagamento: [formaPagamento],
          valor_pago: [pago],
          troco: troco,
          observacoes: observacoes,
        })
        .select()
        .single()

      if (pedidoError) throw pedidoError

      // Criar itens do pedido
      const itensParaInserir = itens.map(item => ({
        pedido_id: pedido.id,
        produto_id: item.produto_id,
        nome: item.nome,
        quantidade: item.quantidade,
        valor_unitario: item.valor_unitario,
      }))

      await supabase
        .from('pedido_itens')
        .insert(itensParaInserir)

      // Buscar tempo de preparo do pedido (máximo dos produtos)
      const { data: produtosData } = await supabase
        .from('produtos')
        .select('tempo_preparo_min')
        .eq('tenant_id', tenantId)
        .in('id', itens.map(i => i.produto_id))

      const tempoMax = produtosData
        ? Math.max(...produtosData.map(p => Number(p.tempo_preparo_min) || 30), 30)
        : 30

      // Gerar mensagem WhatsApp
      const whatsappRes = await fetch('/api/whatsapp-pedido', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          pedido_id: pedido.id,
          tempo_preparo: tempoMax,
          forma_pagamento: [formaPagamento],
        }),
      })
      const whatsappData = await whatsappRes.json()

      setPedidoCriado(pedido)
      setWhatsappUrl(whatsappData.whatsapp_url || '')
      setWhatsappMsg(whatsappData.mensagem || '')

    } catch (error: any) {
      console.error(error)
      alert('Erro ao criar pedido: ' + error.message)
    } finally {
      setLoading(false)
    }
  }

  const copiarMsg = () => {
    navigator.clipboard.writeText(whatsappMsg)
  }

  const novoPedido = () => {
    setPedidoCriado(null)
    setWhatsappUrl('')
    setWhatsappMsg('')
    setItens([])
    setClienteSelecionado(null)
    setFormaPagamento('dinheiro')
    setValorPago('')
    setTroco(0)
    setObservacoes('')
    setTaxaEntrega(0)
  }

  const total = calcularTotal()
  const clienteNovo = clientes.length === 0

  return (
    <div>
      {/* Header */}
      <div className="mb-6">
        <button
          onClick={() => router.back()}
          className="flex items-center gap-2 text-gray-600 hover:text-gray-900 mb-4"
        >
          <ArrowLeft className="w-4 h-4" />
          Voltar
        </button>

        <div className="eyebrow mb-2">Novo Pedido</div>
        <h1 className="text-3xl font-semibold tracking-tight" style={{ color: 'var(--ink)' }}>
          Lançar Pedido
        </h1>
        <p className="hint">Registre um pedido realizado presencialmente ou por telefone</p>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
        {/* Coluna esquerda - Cliente e Endereço */}
        <div className="lg:col-span-1 space-y-6">
          {/* Cliente */}
          <div className="glass p-5">
            <h3 className="font-semibold mb-4 flex items-center gap-2">
              <ShoppingBag className="w-5 h-5 text-green-600" />
              Cliente
            </h3>

            {clienteNovo ? (
              <div className="text-center py-6 text-gray-500">
                <p className="mb-2">Nenhum cliente cadastrado</p>
                <p className="text-sm">Cadastre clientes pelo Marketing para usar aqui</p>
              </div>
            ) : (
              <select
                value={clienteSelecionado?.id || ''}
                onChange={(e) => {
                  const cliente = clientes.find(c => c.id === e.target.value)
                  setClienteSelecionado(cliente || null)
                  if (cliente?.endereco) {
                    setEnderecoEntrega(`${cliente.endereco}${cliente.bairro ? `, ${cliente.bairro}` : ''}`)
                  }
                }}
                className="w-full"
              >
                <option value="">Selecione um cliente</option>
                {clientes.map(cliente => (
                  <option key={cliente.id} value={cliente.id}>
                    {cliente.nome} - {cliente.telefone}
                  </option>
                ))}
              </select>
            )}

            {clienteSelecionado && (
              <div className="mt-4 p-3 bg-green-50 rounded-lg">
                <p className="font-medium">{clienteSelecionado.nome}</p>
                <p className="text-sm text-gray-600">{clienteSelecionado.telefone}</p>
                {clienteSelecionado.endereco && (
                  <p className="text-sm text-gray-600">{clienteSelecionado.endereco}</p>
                )}
              </div>
            )}
          </div>

          {/* Endereço */}
          <div className="glass p-5">
            <h3 className="font-semibold mb-4 flex items-center gap-2">
              <MapPin className="w-5 h-5 text-green-600" />
              Endereço de Entrega
            </h3>

            <textarea
              value={enderecoEntrega}
              onChange={(e) => setEnderecoEntrega(e.target.value)}
              placeholder="Rua, número, bairro..."
              rows={3}
              className="w-full"
            />

            <div className="mt-4">
              <label className="mb-2">Taxa de entrega</label>
              <input
                type="number"
                step="0.01"
                value={taxaEntrega || ''}
                onChange={(e) => setTaxaEntrega(parseFloat(e.target.value) || 0)}
                placeholder="0,00"
                className="w-full"
              />
            </div>
          </div>

          {/* Pagamento */}
          <div className="glass p-5">
            <h3 className="font-semibold mb-4 flex items-center gap-2">
              <CreditCard className="w-5 h-5 text-green-600" />
              Pagamento
            </h3>

            <div className="space-y-3">
              <select
                value={formaPagamento}
                onChange={(e) => setFormaPagamento(e.target.value)}
                className="w-full"
              >
                <option value="dinheiro">Dinheiro</option>
                <option value="pix">PIX</option>
                <option value="cartao_credito">Cartão de Crédito</option>
                <option value="cartao_debito">Cartão de Débito</option>
              </select>

              {formaPagamento === 'dinheiro' && (
                <>
                  <div>
                    <label className="mb-2">Valor pago</label>
                    <input
                      type="number"
                      step="0.01"
                      value={valorPago}
                      onChange={(e) => setValorPago(e.target.value)}
                      placeholder="0,00"
                      className="w-full"
                    />
                  </div>

                  {troco > 0 && (
                    <div className="p-3 bg-amber-50 border border-amber-200 rounded-lg">
                      <p className="text-sm text-amber-800">
                        Troco para: <strong>{formatCurrency(parseFloat(valorPago))}</strong>
                      </p>
                      <p className="font-semibold text-amber-900">
                        Troco: {formatCurrency(troco)}
                      </p>
                    </div>
                  )}
                </>
              )}
            </div>
          </div>

          {/* Observações */}
          <div className="glass p-5">
            <h3 className="font-semibold mb-4">Observações</h3>
            <textarea
              value={observacoes}
              onChange={(e) => setObservacoes(e.target.value)}
              placeholder="Ex: Sem cebola, ponto da carne..."
              rows={2}
              className="w-full"
            />
          </div>
        </div>

        {/* Coluna direita - Produtos */}
        <div className="lg:col-span-2">
          <div className="glass p-5">
            <h3 className="font-semibold mb-4">Produtos</h3>

            {/* Lista de produtos */}
            <div className="grid grid-cols-2 md:grid-cols-3 gap-3 mb-6">
              {produtos.map(produto => (
                <button
                  key={produto.id}
                  onClick={() => adicionarItem(produto)}
                  className="p-3 border rounded-xl text-left hover:border-green-500 hover:bg-green-50 transition-all"
                >
                  <div className="flex justify-between items-start">
                    <span className="font-medium text-sm">{produto.nome}</span>
                    <Plus className="w-4 h-4 text-green-600" />
                  </div>
                  <p className="text-green-600 font-semibold text-sm mt-1">
                    {formatCurrency(produto.preco)}
                  </p>
                </button>
              ))}
            </div>

            {produtos.length === 0 && (
              <div className="text-center py-8 text-gray-500">
                <p>Nenhum produto cadastrado</p>
                <p className="text-sm">Cadastre produtos no Cardápio primeiro</p>
              </div>
            )}

            {/* Itens no pedido */}
            <div className="border-t pt-4 mt-4">
              <h4 className="font-semibold mb-3">
                Itens do Pedido ({itens.length})
              </h4>

              {itens.length === 0 ? (
                <div className="text-center py-8 text-gray-400">
                  <ShoppingBag className="w-12 h-12 mx-auto mb-3 opacity-30" />
                  <p>Adicione produtos ao pedido</p>
                </div>
              ) : (
                <div className="space-y-3">
                  {itens.map(item => (
                    <div
                      key={item.produto_id}
                      className="flex items-center gap-3 p-3 bg-gray-50 rounded-lg"
                    >
                      <div className="flex-1">
                        <p className="font-medium">{item.nome}</p>
                        <p className="text-sm text-gray-500">
                          {formatCurrency(item.valor_unitario)} cada
                        </p>
                      </div>

                      <div className="flex items-center gap-2">
                        <button
                          onClick={() => atualizarQuantidade(item.produto_id, item.quantidade - 1)}
                          className="w-8 h-8 rounded-full border flex items-center justify-center hover:bg-gray-200"
                        >
                          -
                        </button>
                        <span className="font-semibold w-6 text-center">{item.quantidade}</span>
                        <button
                          onClick={() => atualizarQuantidade(item.produto_id, item.quantidade + 1)}
                          className="w-8 h-8 rounded-full border flex items-center justify-center hover:bg-gray-200"
                        >
                          +
                        </button>
                      </div>

                      <p className="font-semibold text-green-600 w-20 text-right">
                        {formatCurrency(item.valor_unitario * item.quantidade)}
                      </p>

                      <button
                        onClick={() => removerItem(item.produto_id)}
                        className="p-2 text-red-500 hover:bg-red-50 rounded-lg"
                      >
                        <Trash2 className="w-4 h-4" />
                      </button>
                    </div>
                  ))}
                </div>
              )}
            </div>

            {/* Totais */}
            {itens.length > 0 && (
              <div className="border-t mt-6 pt-4 space-y-2">
                <div className="flex justify-between text-sm">
                  <span>Subtotal</span>
                  <span>{formatCurrency(total - taxaEntrega)}</span>
                </div>
                {taxaEntrega > 0 && (
                  <div className="flex justify-between text-sm">
                    <span>Taxa de entrega</span>
                    <span>{formatCurrency(taxaEntrega)}</span>
                  </div>
                )}
                <div className="flex justify-between text-xl font-bold pt-2 border-t">
                  <span>Total</span>
                  <span style={{ color: 'var(--green)' }}>{formatCurrency(total)}</span>
                </div>
              </div>
            )}
          </div>

          {/* Botão Finalizar */}
          <button
            onClick={criarPedido}
            disabled={loading || itens.length === 0}
            className="btn-primary w-full mt-6 py-4 text-lg disabled:opacity-50"
          >
            {loading ? (
              'Criando...'
            ) : (
              <>
                <Check className="w-5 h-5" />
                Finalizar Pedido
              </>
            )}
          </button>
        </div>
      </div>

      {/* ✅ TELA DE SUCESSO COM WHATSAPP */}
      {pedidoCriado && (
        <div className="fixed inset-0 bg-black/50 backdrop-blur-sm flex items-center justify-center z-50 p-4">
          <div className="glass-strong rounded-3xl p-8 w-full max-w-lg text-center">
            <div className="size-20 mx-auto mb-4 rounded-full flex items-center justify-center" style={{ background: 'linear-gradient(135deg, #16A34A, #22C55E)' }}>
              <Check size={36} className="text-white" />
            </div>
            <h2 className="text-2xl font-bold mb-2" style={{ color: 'var(--ink)' }}>
              Pedido #{pedidoCriado.id.split('-')[0].toUpperCase()} criado!
            </h2>
            <p className="hint mb-6">{clienteSelecionado?.nome} • {formatCurrency(pedidoCriado.valor_total)}</p>

            {whatsappMsg && (
              <div className="glass-soft p-4 rounded-2xl text-left mb-6" style={{ background: 'rgba(37,211,102,.06)', border: '1px solid rgba(37,211,102,.25)' }}>
                <div className="text-xs font-semibold mb-2" style={{ color: '#25D162' }}>📱 Mensagem WhatsApp</div>
                <pre className="text-xs whitespace-pre-wrap break-all font-mono" style={{ color: 'var(--ink-muted)', maxHeight: 200, overflowY: 'auto' }}>
                  {whatsappMsg}
                </pre>
              </div>
            )}

            <div className="flex gap-3">
              <button
                onClick={copiarMsg}
                className="flex-1 btn-ghost justify-center"
              >
                📋 Copiar mensagem
              </button>
              {whatsappUrl && (
                <a
                  href={whatsappUrl}
                  target="_blank"
                  rel="noopener noreferrer"
                  className="flex-1 flex items-center justify-center gap-2 px-4 py-3 rounded-2xl font-medium text-white transition"
                  style={{ background: '#25D162', boxShadow: '0 4px 14px rgba(37,211,102,.4)' }}
                >
                  <MessageCircle size={18} />
                  Abrir WhatsApp
                </a>
              )}
            </div>

            <button
              onClick={novoPedido}
              className="mt-4 text-sm hint hover:underline"
            >
              ← Lançar outro pedido
            </button>
          </div>
        </div>
      )}
    </div>
  )
}

'use client'

import { useState, useEffect } from 'react'
import Link from 'next/link'
import { createClient } from '@/lib/supabase/client'
import { Clock, Check, Truck, X, Eye, ChevronRight, Plus, MessageCircle, ChevronLeft } from 'lucide-react'
import { Pedido, PedidoStatus } from '@/types'
import { formatCurrency } from '@/lib/utils'
import { activeTenantId } from '@/lib/active-tenant-client'

const STATUS_CONFIG: Record<PedidoStatus, { label: string; color: string; icon: typeof Clock }> = {
  novo: { label: 'Novo', color: 'bg-orange-100 border-orange-300', icon: Clock },
  preparando: { label: 'Preparando', color: 'bg-yellow-100 border-yellow-300', icon: Clock },
  pronto: { label: 'Pronto', color: 'bg-green-100 border-green-300', icon: Check },
  saiu: { label: 'Saiu', color: 'bg-blue-100 border-blue-300', icon: Truck },
  entregue: { label: 'Entregue', color: 'bg-gray-100 border-gray-300', icon: Check },
  cancelado: { label: 'Cancelado', color: 'bg-red-100 border-red-300', icon: X },
}

const NEXT_STATUS: Record<PedidoStatus, PedidoStatus | null> = {
  novo: 'preparando',
  preparando: 'pronto',
  pronto: 'saiu',
  saiu: 'entregue',
  entregue: null,
  cancelado: null,
}

export default function PedidosPage() {
  const [pedidos, setPedidos] = useState<Pedido[]>([])
  const [loading, setLoading] = useState(true)
  const [selectedPedido, setSelectedPedido] = useState<Pedido | null>(null)
  const [itensPedido, setItensPedido] = useState<any[]>([])
  const [motoboys, setMotoboys] = useState<any[]>([])
  const [filtroMotoboy, setFiltroMotoboy] = useState('todos')
  const supabase = createClient()

  useEffect(() => {
    loadPedidos()

    // Subscribe para novos pedidos (polling simples)
    const interval = setInterval(loadPedidos, 10000)
    return () => clearInterval(interval)
  }, [])

  const loadPedidos = async () => {
    const tenantId = await activeTenantId()
    if (!tenantId) { setLoading(false); return }

    const { data } = await supabase
      .from('pedidos')
      .select('*')
      .eq('tenant_id', tenantId)
      .order('data_criacao', { ascending: false })
      .limit(50)

    setPedidos(data || [])
    const { data: entregadores } = await supabase.from('motoboys').select('*').eq('tenant_id', tenantId).order('nome')
    setMotoboys(entregadores || [])
    setLoading(false)
  }

  const atribuirMotoboy = async (pedidoId: string, motoboyId: string) => {
    const { error } = await supabase.from('pedidos').update({ motoboy_id: motoboyId || null }).eq('id', pedidoId)
    if (error) return alert('Erro ao atribuir motoboy')
    setSelectedPedido((p: any) => p?.id === pedidoId ? { ...p, motoboy_id: motoboyId || null } : p)
    loadPedidos()
  }

  const gerarConviteAvaliacao = async (pedidoId: string) => {
    const response = await fetch(`/api/pedidos/${encodeURIComponent(pedidoId)}/avaliacao-convite`, { method: 'POST' })
    const body = await response.json()
    if (!response.ok) return alert(body.error || 'Não foi possível gerar o convite')
    const link = `${window.location.origin}/avaliar/${body.token}`
    await navigator.clipboard.writeText(link)
    alert('Novo convite copiado. O link anterior foi invalidado e este segredo não será exibido novamente.')
  }
  const updateStatus = async (pedido: Pedido, newStatus: PedidoStatus) => {
    const { error } = await supabase
      .from('pedidos')
      .update({
        status: newStatus,
        data_atualizacao: new Date().toISOString()
      })
      .eq('id', pedido.id)

    if (error) {
      console.error('Erro ao atualizar status:', error)
      alert('Erro ao atualizar status')
    } else {
      loadPedidos()
    }
  }

  const loadDetalhesPedido = async (pedido: Pedido) => {
    setSelectedPedido(pedido)
    const { data } = await supabase
      .from('pedido_itens')
      .select('*')
      .eq('pedido_id', pedido.id)
    setItensPedido(data || [])
  }

  const formatDate = (date: string) => {
    return new Date(date).toLocaleString('pt-BR', {
      day: '2-digit',
      month: '2-digit',
      hour: '2-digit',
      minute: '2-digit',
    })
  }

  if (loading) {
    return <div className="text-center py-8">Carregando...</div>
  }

  return (
    <div>
      <div className="mb-6">
        <div className="flex items-center justify-between">
          <div>
            <div className="eyebrow mb-2">Atendimento</div>
            <h1 className="text-3xl font-semibold tracking-tight mb-1" style={{ color: 'var(--ink)' }}>
              Pedidos
            </h1>
            <p className="hint">Gerencie os pedidos do seu delivery</p>
          </div>
          <Link
            href="/pedidos/novo"
            className="btn-primary flex items-center gap-2"
          >
            <Plus className="w-4 h-4" />
            Novo Pedido
          </Link>
        </div>
      </div>

      {/* Stats Bar */}
      <div className="flex gap-4 mb-6 overflow-x-auto pb-2">
        {(['novo', 'preparando', 'pronto', 'saiu'] as PedidoStatus[]).map((status) => {
          const count = pedidos.filter((p) => p.status === status).length
          const config = STATUS_CONFIG[status]
          return (
            <div
              key={status}
              className={`${config.color} border rounded-lg px-4 py-2 flex items-center gap-2 whitespace-nowrap`}
            >
              <config.icon className="w-4 h-4" />
              <span className="font-medium">{config.label}</span>
              <span className="bg-white px-2 py-0.5 rounded-full text-sm">{count}</span>
            </div>
          )
        })}
      </div>

      <div className="bg-white rounded-xl border p-3 mb-3 flex items-center gap-2">
        <label className="text-sm font-medium">Filtrar motoboy:</label>
        <select className="form-input max-w-xs" value={filtroMotoboy} onChange={e => setFiltroMotoboy(e.target.value)}><option value="todos">Todos</option><option value="sem">Sem motoboy</option>{motoboys.map(m => <option key={m.id} value={m.id}>{m.nome}</option>)}</select>
      </div>
      {/* Lista de Pedidos */}
      <div className="bg-white rounded-xl shadow-sm overflow-hidden">
        {pedidos.length > 0 ? (
          <div className="divide-y">
            {pedidos.filter((p: any) => filtroMotoboy === 'todos' || (filtroMotoboy === 'sem' ? !p.motoboy_id : p.motoboy_id === filtroMotoboy)).map((pedido) => {
              const config = STATUS_CONFIG[pedido.status]
              const StatusIcon = config.icon
              const nextStatus = NEXT_STATUS[pedido.status]

              return (
                <div
                  key={pedido.id}
                  className={`p-4 flex items-center gap-4 hover:bg-gray-50 ${
                    pedido.status === 'novo' ? 'bg-orange-50/50' : ''
                  }`}
                >
                  <div className={`p-2 rounded-lg ${config.color}`}>
                    <StatusIcon className="w-5 h-5" />
                  </div>

                  <div className="flex-1">
                    <div className="flex items-center gap-2">
                      <span className="font-medium">#{pedido.id.slice(0, 8)}</span>
                      <span className="text-sm text-gray-500">{formatDate(pedido.data_criacao)}</span>
                    </div>
                    <p className="text-sm text-gray-600">
                      {pedido.forma_pagamento.join(', ')} • {formatCurrency(pedido.valor_total)}
                    </p>
                  </div>

                  <div className="flex items-center gap-2">
                    <select aria-label="Motoboy" className="form-input text-xs max-w-36" value={(pedido as any).motoboy_id || ''} onChange={e => atribuirMotoboy(pedido.id, e.target.value)}><option value="">Sem motoboy</option>{motoboys.filter(m => m.ativo || m.id === (pedido as any).motoboy_id).map(m => <option key={m.id} value={m.id}>{m.nome}</option>)}</select>
                    {nextStatus && (
                      <button
                        onClick={() => updateStatus(pedido, nextStatus)}
                        className="px-3 py-1.5 bg-blue-600 text-white text-sm rounded-lg hover:bg-blue-700 flex items-center gap-1"
                      >
                        {STATUS_CONFIG[nextStatus].label}
                        <ChevronRight className="w-4 h-4" />
                      </button>
                    )}

                    {pedido.status !== 'cancelado' && pedido.status !== 'entregue' && (
                      <button
                        onClick={() => updateStatus(pedido, 'cancelado')}
                        className="p-1.5 text-red-600 hover:bg-red-50 rounded-lg"
                      >
                        <X className="w-4 h-4" />
                      </button>
                    )}

                    <button
                      onClick={() => loadDetalhesPedido(pedido)}
                      className="p-1.5 text-gray-600 hover:bg-gray-100 rounded-lg"
                    >
                      <Eye className="w-4 h-4" />
                    </button>
                  </div>
                </div>
              )
            })}
          </div>
        ) : (
          <div className="p-12 text-center">
            <Clock className="w-12 h-12 text-gray-400 mx-auto mb-4" />
            <h3 className="text-lg font-medium text-gray-900 mb-2">Nenhum pedido</h3>
            <p className="text-gray-500">Os pedidos aparecerão aqui quando chegarem</p>
          </div>
        )}
      </div>

      {/* Modal de Detalhes */}
      {selectedPedido && (
        <div className="fixed inset-0 bg-black/50 flex items-center justify-center z-50 p-4">
          <div className="bg-white rounded-xl w-full max-w-lg max-h-[80vh] overflow-auto">
            <div className="p-6 border-b">
              <div className="flex justify-between items-start">
                <div>
                  <h2 className="text-xl font-bold">Pedido #{selectedPedido.id.slice(0, 8)}</h2>
                  <p className="text-gray-500">{formatDate(selectedPedido.data_criacao)}</p>
                </div>
                <button onClick={() => setSelectedPedido(null)} className="text-gray-400 hover:text-gray-600">
                  <X className="w-6 h-6" />
                </button>
              </div>
              <span className={`inline-block mt-2 px-3 py-1 rounded-full text-sm ${STATUS_CONFIG[selectedPedido.status].color}`}>
                {STATUS_CONFIG[selectedPedido.status].label}
              </span>
            </div>

            <div className="p-6 space-y-6">
              {/* Itens */}
              <div>
                <h3 className="font-medium mb-3">Itens</h3>
                <div className="space-y-2">
                  {itensPedido.map((item) => (
                    <div key={item.id} className="flex justify-between text-sm">
                      <span>{item.quantidade}x {item.nome}</span>
                      <span className="font-medium">{formatCurrency(item.valor_unitario * item.quantidade)}</span>
                    </div>
                  ))}
                </div>
              </div>

              {/* Totais */}
              <div className="border-t pt-4 space-y-2">
                <div className="flex justify-between text-sm">
                  <span>Subtotal</span>
                  <span>{formatCurrency(selectedPedido.valor_total - selectedPedido.taxa_entrega)}</span>
                </div>
                <div className="flex justify-between text-sm">
                  <span>Taxa de entrega</span>
                  <span>{formatCurrency(selectedPedido.taxa_entrega)}</span>
                </div>
                <div className="flex justify-between font-bold text-lg">
                  <span>Total</span>
                  <span>{formatCurrency(selectedPedido.valor_total)}</span>
                </div>
              </div>

              {/* Pagamento */}
              <div>
                <h3 className="font-medium mb-2">Pagamento</h3>
                <p className="text-sm text-gray-600">
                  {selectedPedido.forma_pagamento.map((forma, i) => (
                    <span key={forma}>
                      {forma}: {formatCurrency(selectedPedido.valor_pago[i] || 0)}
                      {i < selectedPedido.forma_pagamento.length - 1 && ', '}
                    </span>
                  ))}
                  {selectedPedido.troco > 0 && (
                    <span> • Troco: {formatCurrency(selectedPedido.troco)}</span>
                  )}
                </p>
              </div>

              {/* Observações */}
              {selectedPedido.observacoes && (
                <div>
                  <h3 className="font-medium mb-2">Observações</h3>
                  <p className="text-sm text-gray-600">{selectedPedido.observacoes}</p>
                </div>
              )}
              {/* Botões de ação no modal */}
              <div className="border-t pt-4"><h3 className="font-medium mb-2">Entregador</h3><select className="form-input" value={(selectedPedido as any).motoboy_id || ''} onChange={e => atribuirMotoboy(selectedPedido.id, e.target.value)}><option value="">Sem motoboy atribuido</option>{motoboys.map(m => <option key={m.id} value={m.id}>{m.nome} ({m.tipo_comissao === 'fixa' ? `R$ ${Number(m.comissao_fixa).toFixed(2)}` : `${Number(m.comissao_percent).toFixed(1)}%`})</option>)}</select>{(selectedPedido as any).motoboy_comissao != null && <p className="text-sm text-gray-500 mt-1">Comissao registrada: {formatCurrency(Number((selectedPedido as any).motoboy_comissao))}</p>}{selectedPedido.status === 'entregue' && <button type="button" className="text-sm text-blue-600 underline mt-2 block" onClick={() => gerarConviteAvaliacao(selectedPedido.id)}>Gerar e copiar novo convite de avaliação</button>}</div>
              <div className="border-t pt-4 flex flex-wrap gap-2">
                {NEXT_STATUS[selectedPedido.status] && (
                  <button
                    onClick={() => {
                      updateStatus(selectedPedido, NEXT_STATUS[selectedPedido.status]!)
                      setSelectedPedido({ ...selectedPedido, status: NEXT_STATUS[selectedPedido.status]! })
                    }}
                    className="flex-1 px-3 py-2 bg-blue-600 text-white text-sm rounded-lg hover:bg-blue-700 flex items-center justify-center gap-1"
                  >
                    {STATUS_CONFIG[NEXT_STATUS[selectedPedido.status]!].label}
                    <ChevronRight className="w-4 h-4" />
                  </button>
                )}

                {selectedPedido.status !== 'cancelado' &&
                  selectedPedido.status !== 'entregue' &&
                  NEXT_STATUS[selectedPedido.status] && (
                    <button
                      onClick={() => {
                        if (!confirm('Cancelar este pedido?')) return
                        updateStatus(selectedPedido, 'cancelado')
                        setSelectedPedido({ ...selectedPedido, status: 'cancelado' })
