import { useEffect,useState } from 'react';import { createClient } from '@/lib/supabase/client';import { Gift } from 'lucide-react'
async function tenantAtivo(){const r=await fetch('/api/auth/session',{cache:'no-store'});const b=await r.json();if(!r.ok||!b.tenant?.id)throw new Error('Loja ativa não encontrada');return String(b.tenant.id)}
export default function SorteiosPage(){const db=createClient(),[cs,setCs]=useState<any[]>([]),[msg,setMsg]=useState(''),[form,setForm]=useState({nome:'',descricao:'',inicio_em:'',fim_em:'',valor_minimo_pedido:'0',cupons_por_pedido:'1'});async function load(){try{const tid=await tenantAtivo();const {data,error}=await db.from('campanhas_sorteio').select('*,cupons_sorteio(count),vencedor:cupons_sorteio!campanhas_sorteio_vencedor_cupom_id_fkey(numero,cliente_nome,cliente_whatsapp)').eq('tenant_id',tid).order('created_at',{ascending:false});if(error)throw error;setCs(data||[])}catch(e:any){setMsg(e.message)}}useEffect(()=>{load()},[]);async function criar(e:React.FormEvent){e.preventDefault();const tid=await tenantAtivo();const {error}=await db.from('campanhas_sorteio').insert({...form,tenant_id:tid,valor_minimo_pedido:Number(form.valor_minimo_pedido),cupons_por_pedido:Number(form.cupons_por_pedido)});setMsg(error?.message||'Campanha criada.');if(!error)load()}async function sortear(id:string){if(!confirm('O resultado será definitivo e auditável. Continuar?'))return;const {error}=await db.rpc('sortear_campanha',{p_campanha_id:id});setMsg(error?.message||'Sorteio realizado.');load()}return <div><header className="glass p-5 mb-4"><p className="eyebrow flex gap-1"><Gift size={13}/>Campanhas</p><h1 className="text-3xl font-bold">Sorteios</h1></header><form onSubmit={criar} className="glass p-4 grid md:grid-cols-3 gap-3 mb-4"><input required placeholder="Nome" value={form.nome} onChange={e=>setForm({...form,nome:e.target.value})}/><input placeholder="Descrição" value={form.descricao} onChange={e=>setForm({...form,descricao:e.target.value})}/><input required type="datetime-local" value={form.inicio_em} onChange={e=>setForm({...form,inicio_em:e.target.value})}/><input required type="datetime-local" value={form.fim_em} onChange={e=>setForm({...form,fim_em:e.target.value})}/><input type="number" step=".01" value={form.valor_minimo_pedido} onChange={e=>setForm({...form,valor_minimo_pedido:e.target.value})}/><input type="number" min="1" value={form.cupons_por_pedido} onChange={e=>setForm({...form,cupons_por_pedido:e.target.value})}/><button className="btn-primary">Criar campanha</button></form>{msg&&<p className="mb-3">{msg}</p>}<div className="grid md:grid-cols-2 gap-4">{cs.map(c=><article className="glass p-5" key={c.id}><h2 className="font-bold">{c.nome}</h2><p>{c.cupons_sorteio?.[0]?.count||0} cupons</p>{c.vencedor?<p className="mt-3"><b>Vencedor #{c.vencedor.numero}</b> — {c.vencedor.cliente_nome}</p>:<button onClick={()=>sortear(c.id)} className="btn-primary mt-3">Realizar sorteio</button>}</article>)}</div></div>}

import { Suspense } from 'react'
import { notFound } from 'next/navigation'

async function TestContent() {
  let debug: any = {}

  try {
    // Chama a API via fetch do server-side
    const { createClient } = await import('@/lib/supabase/server')
    const supabase = await createClient()
    const { data: { session } } = await supabase.auth.getSession()

    debug = {
      tipo: 'server-side',
      sessionExiste: !!session,
      userId: session?.user?.id || null,
      userEmail: session?.user?.email || null,
    }
  } catch (err: any) {
    debug = { tipo: 'erro', erro: err.message }
  }

  return (
    <div style={{ padding: 40, fontFamily: 'Arial', background: '#000', color: '#0f0', minHeight: '100vh' }}>
      <h1 style={{ fontSize: 24, marginBottom: 20 }}>🔐 Teste de Sessão (Server-Side)</h1>
      <pre style={{ background: '#111', padding: 20, borderRadius: 8, overflow: 'auto' }}>
        {JSON.stringify(debug, null, 2)}
      </pre>
      <div style={{ marginTop: 20 }}>
        {debug.sessionExiste ? (
          <p style={{ color: '#0f0', fontSize: 18 }}>✅ SESSÃO EXISTE!</p>
        ) : (
          <p style={{ color: '#f00', fontSize: 18 }}>❌ SEM SESSÃO</p>
        )}
      </div>
    </div>
  )
}

export default function TestPage() {
  if (process.env.NODE_ENV === 'production') notFound()

  return (
    <Suspense fallback={<div style={{ padding: 40, background: '#000', color: '#fff' }}>Carregando...</div>}>
      <TestContent />
    </Suspense>
  )
}

