// Criar lojista — cria usuário no Auth + insere tenant
// Fluxo: status = 'pending_approval' (sem confirmação de email necessária)
// Admin aprova → muda pra 'active'
export async function POST(request: Request) {
  if (!(await getAdminSession())) return adminUnauthorizedResponse()
  try {
    const supabase = getAdminClient()
    const body = await request.json()

    const {
      nome, slug, email, password,
      categoria, telefone, estado, cidade, endereco, numero,
      nome_responsavel, cpf,
      valor_mensalidade,
    } = body

    if (!nome || !email || !password) {
      return NextResponse.json(
        { error: 'Nome, email e senha são obrigatórios' },
        { status: 400 }
      )
    }

    // Slug: se não veio, gera a partir do nome
    const finalSlug = (slug || nome)
      .toLowerCase()
      .normalize('NFD').replace(/[̀-ͯ]/g, '')
      .replace(/[^a-z0-9]+/g, '-')
      .replace(/^-|-$/g, '')

    // Verificar se email já existe
    const { data: existingUsers } = await supabase.auth.admin.listUsers()
    if (existingUsers?.users?.some((u) => u.email?.toLowerCase() === email.toLowerCase())) {
      return NextResponse.json({ error: 'Este email já está cadastrado' }, { status: 400 })
    }

    // Verificar slug duplicado
    const { data: existingSlug } = await supabase
      .from('tenants')
      .select('id')
      .eq('slug', finalSlug)
      .single()

    if (existingSlug) {
      return NextResponse.json({ error: 'Slug já está em uso' }, { status: 400 })
    }

    // Endereço completo com número
    const enderecoCompleto = numero ? `${endereco}, ${numero}` : endereco

    // 1. Criar usuário no Auth — email_confirm: true (sem link de confirmação)
    const { data: authData, error: authError } = await supabase.auth.admin.createUser({
      email,
      password,
      email_confirm: true, // Admin cria → já confirmado
      user_metadata: {
        nome,
        categoria,
        telefone,
        estado,
        cidade,
        endereco: enderecoCompleto,
        numero,
        nome_responsavel,
        cpf,
      },
    })

    if (authError) throw authError

    const userId = authData.user.id

    // 2. Criar tenant com status 'pending_approval'
    const { data: tenant, error: tenantError } = await supabase
      .from('tenants')
      .insert({
        id: userId,
        slug: finalSlug,
        nome,
        email,
        categoria,
        telefone,
        estado,
        cidade,
        endereco: enderecoCompleto,
        numero,
        nome_responsavel,
        cpf,
        status: 'pending_approval',
        valor_mensalidade: Number(valor_mensalidade) || 99.90,
        status_pagamento: 'pendente',
      })
      .select()
      .single()

    if (tenantError) throw tenantError

    return NextResponse.json({ tenant })
  } catch (error: any) {
    console.error('Erro ao criar tenant:', error)
    return NextResponse.json({ error: error.message || 'Erro ao criar lojista' }, { status: 500 })
  }
}

// Atualizar lojista — qualquer campo editável + status de aprovação
export async function PUT(request: Request) {
  if (!(await getAdminSession())) return adminUnauthorizedResponse()
  try {
    const supabase = getAdminClient()
    const body = await request.json()

    const { id, ...updates } = body

    if (!id) {
      return NextResponse.json({ error: 'ID necessário' }, { status: 400 })
    }

    // Se a senha veio pra atualizar, atualizar via admin API
    if (updates.password) {
      const { error: pwError } = await supabase.auth.admin.updateUserById(id, {
        password: updates.password,
      })
      if (pwError) throw pwError
      delete updates.password
    }

    // Se o email veio pra atualizar
    if (updates.email) {
      const { error: emailError } = await supabase.auth.admin.updateUserById(id, {
        email: updates.email,
      })
      if (emailError) throw emailError
      delete updates.email
    }

    // Atualizar tenant
    const { data, error } = await supabase
      .from('tenants')
      .update(updates)
      .eq('id', id)
      .select()
      .single()

    if (error) throw error

    return NextResponse.json({ tenant: data })
  } catch (error: any) {
    console.error('Erro ao atualizar tenant:', error)
    return NextResponse.json({ error: error.message || 'Erro ao atualizar lojista' }, { status: 500 })
  }
}

export async function DELETE(request: Request) {
  if (!(await getAdminSession())) return adminUnauthorizedResponse()
  try {
    const supabase = getAdminClient()
    const { searchParams } = new URL(request.url)
    const id = searchParams.get('id')

    if (!id) {
      return NextResponse.json({ error: 'ID necessário' }, { status: 400 })
    }

    // Deletar usuário do Auth (cascade no tenant)
    await supabase.auth.admin.deleteUser(id)

    return NextResponse.json({ success: true })
  } catch (error: any) {
    console.error('Erro ao deletar tenant:', error)
    return NextResponse.json({ error: error.message || 'Erro ao deletar lojista' }, { status: 500 })
  }
}

﻿import { NextRequest, NextResponse } from 'next/server'
import { authenticatedTenant } from '@/lib/tenant-auth'

// GET /api/analytics?periodo=7d|30d|24h|all
// Retorna page_views agrupados por dia + total + unicos
export async function GET(req: NextRequest) {
  try {
    const { supabase, tenantId } = await authenticatedTenant(['owner', 'manager'])

    const url = new URL(req.url)
    const periodo = url.searchParams.get('periodo') || '7d'

    let desde = new Date()
    if (periodo === '24h') desde.setDate(desde.getDate() - 1)
    else if (periodo === '7d') desde.setDate(desde.getDate() - 7)
    else if (periodo === '30d') desde.setDate(desde.getDate() - 30)
    else if (periodo === 'all') desde = new Date('2000-01-01')

    const { data, error } = await supabase
      .from('page_views')
      .select('created_at, slug')
      .eq('tenant_id', tenantId)
      .gte('created_at', desde.toISOString())

    if (error) throw error

    // Agrupar por dia
    const porDia: Record<string, number> = {}
    for (const v of data || []) {
      const d = new Date(v.created_at)
      const key = `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, '0')}-${String(d.getDate()).padStart(2, '0')}`
      porDia[key] = (porDia[key] || 0) + 1
    }

    const total = (data || []).length

    return NextResponse.json({
      total,
      porDia: Object.entries(porDia)
        .map(([data, views]) => ({ data, views }))
        .sort((a, b) => a.data.localeCompare(b.data)),
    })
  } catch (e: any) {
    return NextResponse.json({ error: e.message }, { status: 500 })
  }
}

﻿import { NextRequest, NextResponse } from 'next/server'
import { createClient } from '@/lib/supabase/server'
import { createClient as createSupabaseClient } from '@supabase/supabase-js'

// Simples: login server-side, retorna um token no cookie
export async function POST(request: NextRequest) {
  try {
    const { email, password } = await request.json()

    if (!email || !password) {
      return NextResponse.json({ error: 'Email e senha obrigatórios' }, { status: 400 })
    }

    const supabase = await createClient()

    // Login
    const { data, error } = await supabase.auth.signInWithPassword({ email, password })

    if (error || !data.user) {
      return NextResponse.json({ error: error?.message || 'Login falhou' }, { status: 401 })
    }

    // Resolve a loja com service role somente depois de validar as credenciais.
    // A associação ativa em usuarios_loja é a única fonte de autorização.
    const admin = createSupabaseClient(
      process.env.NEXT_PUBLIC_SUPABASE_URL!,
      process.env.SUPABASE_SERVICE_ROLE_KEY!,
      { auth: { persistSession: false, autoRefreshToken: false } }
    )
    const { data: memberships } = await admin
      .from('usuarios_loja')
      .select('tenant_id, role, ativo')
      .eq('user_id', data.user.id)
      .eq('ativo', true)
    const ordered = [...(memberships || [])].sort((a, b) =>
      ((a.role === 'owner' ? 0 : 1) - (b.role === 'owner' ? 0 : 1)) || a.tenant_id.localeCompare(b.tenant_id)
    )
    const membership = ordered[0]
    const tenantId = membership?.tenant_id
    const { data: tenant } = await admin
      .from('tenants')
      .select('id, nome, status')
      .eq('id', tenantId)
      .maybeSingle()

    if (!tenant) {
      await supabase.auth.signOut()
      return NextResponse.json({ error: 'Loja nao encontrada. Contate o suporte.' }, { status: 403 })
    }
    if (!['active', 'pending_approval'].includes(tenant.status)) {
      await supabase.auth.signOut()
      return NextResponse.json({ error: 'Acesso da loja suspenso ou inativo.' }, { status: 403 })
    }

    const response = NextResponse.json({
      success: true,
      userId: data.user.id,
      tenant,
      role: membership!.role,
    })
    response.cookies.set('wd_active_tenant', tenantId!, {
      httpOnly: true, sameSite: 'lax', secure: process.env.NODE_ENV === 'production',
      path: '/', maxAge: 60 * 60 * 24 * 365,
    })
    return response

  } catch (err: any) {
    return NextResponse.json({ error: err.message }, { status: 500 })
  }
}

