    </div>
  )
}

function ToggleField({ label, description, checked, onChange }: {
  label: string
  description: string
  checked: boolean
  onChange: (v: boolean) => void
}) {
  return (
    <div className="flex items-center justify-between p-4 rounded-xl" style={{ background: 'rgba(0,0,0,.03)' }}>
