                className="form-input"
              />
            </Field>
          </CardSection>

          {/* ====== CARD 2: Foto ====== */}
          <CardSection title="Foto do item">
            <ImageUploader
              value={form.imagem_url}
              onChange={(url, path) => setForm({ ...form, imagem_url: url, imagem_path: path || '' })}
