                <input
                  type="number"
                  min={0}
                  value={form.limite_vendas_turno ?? ''}
                  onChange={(e) =>
                    setForm({
                      ...form,
                      limite_vendas_turno: e.target.value,
                    })
                  }
                  className="form-input"
