          </CardSection>
        </div>

        {/* ============ FOOTER ============ */}
        <div className="flex items-center justify-between gap-3 px-6 py-4 border-t bg-white" style={{ borderColor: 'var(--line-strong)' }}>
          <div className="flex-1">
            {erro && (
